    'maint.aide_tech_title' => "The reporter",
    'maint.aide_tech_sub' => "Who is reporting this intervention?",
    'maint.aide_tech_body' => <<<'HTML'
<p>The reporter is the person opening the ticket — the one who noticed the fault or has a task to be carried out.</p>
            <ul class="aide-list">
                <li><i class="fa-solid fa-lock" style="color:var(--accent);"></i> If you are a technician, this field is locked to your own name.</li>
                <li><i class="fa-solid fa-user-shield" style="color:var(--accent);"></i> An administrator can designate any team member.</li>
            </ul>
HTML,

    'maint.aide_assign_tech_title' => "Planned technicians",
    'maint.aide_assign_tech_sub' => "Pre-assign one or more technicians right at creation (optional)",
    'maint.aide_assign_tech_body' => <<<'HTML'
<p>This field, reserved for administrators, lets you check one or more technicians in advance to handle this intervention — handy for organizing the schedule. Leave "Not assigned" checked if no one is designated yet: whoever picks up the ticket will assign it to themselves.</p>
            <div class="aide-callout aide-callout-info"><i class="fa-solid fa-circle-info"></i><div>This is only an indication: whoever actually logs time on the ticket becomes the official technician.</div></div>
HTML,

    'maint.aide_sous_traitant_title' => "Subcontracted intervention",
    'maint.aide_sous_traitant_sub' => "When an external company is involved",
    'maint.aide_sous_traitant_body' => <<<'HTML'
<p>Check this box if the intervention is entrusted to an external provider rather than the in-house team.</p>
            <ul class="aide-list">
                <li><i class="fa-solid fa-list-check" style="color:var(--gelpam-orange);"></i> Then choose the company from the list that appears just below.</li>
                <li><i class="fa-solid fa-file-pdf" style="color:var(--gelpam-orange);"></i> Once the order is created, a "Generate PPP" (Prevention Plan) button will appear on its record.</li>
            </ul>
HTML,

    'maint.aide_localisation_title' => "Locate the machine",
    'maint.aide_localisation_sub' => "Search or tile navigation",
    'maint.aide_localisation_body' => <<<'HTML'
<p>Two ways to find the machine: type its name (or a zone, a sector...) in the <b>search</b> bar, or click step by step through the <b>Plant → Sector → Line → Zone → Machine</b> tiles.</p>
            <div class="aide-callout aide-callout-tip"><i class="fa-solid fa-lightbulb"></i><div>The breadcrumb above the tiles lets you go back at any time to change plant, sector, etc. No worries if a sector has no "Line": this step is skipped automatically.</div></div>
HTML,

    'maint.aide_machine_title' => "Selecting the machine",
    'maint.aide_machine_sub' => "The last link in the location chain",
    'maint.aide_machine_body' => <<<'HTML'
<p>The search bar filters instantly across all machines (name, zone, sector, plant): ideal when you already know the machine. Otherwise, the tiles below let you navigate step by step to the equipment in question. This keeps a clean maintenance history, machine by machine.</p>
            <div class="aide-callout aide-callout-warn"><i class="fa-solid fa-triangle-exclamation"></i><div>Machine not found? The field becomes free text — have an administrator add it to the Machine Fleet for next time.</div></div>
HTML,

    'maint.aide_date_title' => "Intervention date",
    'maint.aide_date_sub' => "Today by default",
    'maint.aide_date_body' => "<p>Today's date is pre-filled automatically. You can change it if you are reporting a past intervention, for example to catch up on a forgotten entry.</p>",

    'maint.aide_type_title' => "Intervention type",
    'maint.aide_type_sub' => "Corrective, Preventive or Project?",
    'maint.aide_type_body' => <<<'HTML'
<ul class="aide-list">
                <li><i class="fa-solid fa-screwdriver-wrench" style="color:var(--accent);"></i> <b>Corrective</b>: repairing a fault that has already occurred.</li>
                <li><i class="fa-solid fa-calendar-check" style="color:var(--accent);"></i> <b>Preventive</b>: planned inspection or servicing, before a fault occurs.</li>
                <li><i class="fa-solid fa-helmet-safety" style="color:var(--accent);"></i> <b>Project</b>: an installation, modification or improvement project.</li>
            </ul>
HTML,

    'maint.aide_prio_title' => "Priority",
    'maint.aide_prio_sub' => "Normal or Urgent?",
    'maint.aide_prio_body' => <<<'HTML'
<ul class="aide-list">
                <li><i class="fa-solid fa-circle-check" style="color:var(--accent);"></i> <b>Normal</b>: standard intervention, to be handled in order.</li>
                <li><i class="fa-solid fa-bell" style="color:var(--danger);"></i> <b>Urgent</b>: line stopped or safety hazard.</li>
            </ul>
            <div class="aide-callout aide-callout-warn"><i class="fa-solid fa-bell"></i><div>An "Urgent" ticket blinks red in the table until it is picked up — reserve this level for genuine emergencies.</div></div>
HTML,

    'maint.aide_casse_title' => "Damage",
    'maint.aide_casse_sub' => "Accidental equipment breakage",
    'maint.aide_casse_body' => "<p>Check this if the intervention follows mishandling or an accidental impact on the equipment. This tracks the breakage rate in the statistics.</p>",

    'maint.aide_verif_vis_title' => "Fastener check",
    'maint.aide_verif_vis_sub' => "Quality / Audit requirement",
    'maint.aide_verif_vis_body' => <<<'HTML'
<p>By checking this box, you formally certify that you have checked the integrity of the equipment's fasteners.</p>
            <div class="aide-callout aide-callout-warn"><i class="fa-solid fa-shield-halved"></i><div>You are certifying that all screws, nuts and fasteners removed during the intervention have been put back and properly tightened — ruling out any risk of a foreign object falling.</div></div>
HTML,

    'maint.aide_desc_title' => "Description",
    'maint.aide_desc_sub' => "The field most read by your colleagues",
    'maint.aide_desc_body' => <<<'HTML'
<p>Describe the symptom or task as precisely as possible.</p>
            <div class="aide-callout aide-callout-tip"><i class="fa-solid fa-thumbs-up"></i><div><b>Good example:</b> "Push cylinder stuck in the up position"</div></div>
            <div class="aide-callout aide-callout-warn"><i class="fa-solid fa-thumbs-down"></i><div><b>Avoid:</b> "Broken"</div></div>
HTML,

    'maint.aide_duree_title' => "Time calculation (hundredths)",
    'maint.aide_duree_sub' => "The GMAO uses hundredths of an hour",
    'maint.aide_duree_body' => <<<'HTML'
<ul class="aide-list">
                <li><i class="fa-solid fa-clock" style="color:var(--accent);"></i> 15 min = <b>0.25</b></li>
                <li><i class="fa-solid fa-clock" style="color:var(--accent);"></i> 30 min = <b>0.50</b></li>
                <li><i class="fa-solid fa-clock" style="color:var(--accent);"></i> 45 min = <b>0.75</b></li>
                <li><i class="fa-solid fa-clock" style="color:var(--accent);"></i> 1 hour = <b>1.00</b></li>
            </ul>
            <div class="aide-callout aide-callout-tip"><i class="fa-solid fa-lightbulb"></i><div>Example: for 1h30, enter <b>1.5</b></div></div>
HTML,

    'maint.aide_demandes_title' => "Pending requests",
    'maint.aide_demandes_sub' => "Reports from another department",
    'maint.aide_demandes_body' => "<p>Reports made by the various departments (Management, Production, Safety, Quality, Logistics, Agronomy) are shown here. You must validate them to turn them into Work Orders.</p>",

    'maint.aide_photos_title' => "Photos",
    'maint.aide_photos_sub' => "Optional, but very useful for locating the fault",
    'maint.aide_photos_body' => <<<'HTML'
<p>Add one or more photos of the location or the faulty equipment — on tablet/phone, the camera is offered directly in the picker.</p>
            <div class="aide-callout aide-callout-tip"><i class="fa-solid fa-lightbulb"></i><div>Optional: the order can be created without any photo. Photos are sent once the ticket is created.</div></div>
HTML,

