    'aide_connexion.modes_lede' => "The same login screen serves two very different audiences, with two distinct code systems. First work out which one applies to you.",
    'aide_connexion.route_maint_tag' => "Admin, Technician",
    'aide_connexion.route_maint_title' => "Maintenance Team",
    'aide_connexion.route_maint_li1' => "You select <b>your personal name</b> from the list.",
    'aide_connexion.route_maint_li2' => "You enter <b>your own personal secret code</b>.",
    'aide_connexion.route_maint_li3' => "You land on the <b>GMAO home screen</b>, with all its tiles (Entry & History, Schedule, KPI...).",
    'aide_connexion.route_service_tag' => "Production, Quality, Safety, HR, Accounting, Logistics, Agronomy...",
    'aide_connexion.route_service_title' => "Other services",
    'aide_connexion.route_service_li1' => "You select <b>your service's name</b> (e.g. \"S. Production\"), not your personal name.",
    'aide_connexion.route_service_li2' => "You enter the <b>service's general code</b> — the same one used by the whole team, not an individual code.",
    'aide_connexion.route_service_li3' => "You land on the <b>\"Submit a work request\"</b> portal, not on the GMAO itself.",
    'aide_connexion.modes_warn' => "<b>Other services only:</b> the service code just opens the portal. For <b>every request</b> you submit, an extra step asks for your <b>name</b> and a <b>personal code of at least 4 digits</b> — different from the service's login code. This personal code acts as an electronic signature: it proves you're the one who submitted that specific request. Everything is explained in <a href=\"aide_service.php\">the dedicated article on the request portal</a>.",
    'aide_connexion.connexion_lede' => "No email address or classic password here: you pick your name (or your service) from a list, then enter the matching code.",
    'aide_connexion.shot_login_alt' => "GMAO login screen",
    'aide_connexion.shot_login_cap' => "The login screen: a name, a code, a button.",
    'aide_connexion.step1_title' => "Choose your name, or your service",
    'aide_connexion.step1_desc' => "Open the <b>\"Who are you?\"</b> dropdown. The Maintenance team finds their personal name there; other services select their service's name (e.g. \"S. Quality\").",
    'aide_connexion.step2_title' => "Enter the matching code",
    'aide_connexion.step2_desc' => "Maintenance team: your personal secret code. Other services: your service's general code, the one the whole team uses. It's masked on screen, like a password.",
    'aide_connexion.step3_title' => "Click \"SE CONNECTER\" (Log in)",
    'aide_connexion.step3_desc' => "You're automatically redirected to your home screen.",
    'aide_connexion.tip_code' => "Never received a code, or need to change it? Use the <b>\"Change my secret code\"</b> link under the login button, or ask an administrator.",
    'aide_connexion.langue_lede' => "The whole GMAO — this login screen included — is available in French, English and Dutch.",
    'aide_connexion.langue_step1_title' => "Spot the three \"FR / EN / NL\" boxes",
    'aide_connexion.langue_step1_desc' => "They're shown at the top right of the login screen, and in the top bar on every page once you're logged in.",
    'aide_connexion.langue_step2_title' => "Click the language you want",
    'aide_connexion.langue_step2_desc' => "The page reloads instantly in that language — no need to log in again.",
    'aide_connexion.langue_step3_title' => "The choice is remembered",
    'aide_connexion.langue_step3_desc' => "You only need to do it once per device/browser: the GMAO then remembers your language on every visit.",
    'aide_connexion.langue_tip' => "Only the interface itself is translated (menus, buttons, labels). Content that you or your colleagues have entered — machine names, intervention reports, categories created in Settings, etc. — stays displayed exactly as written, whichever language is selected.",
    'aide_connexion.erreur_lede' => "A red message appears if the name and code don't match.",
    'aide_connexion.shot_erreur_alt' => "Error message: incorrect username or code",
    'aide_connexion.shot_erreur_cap' => "This message doesn't specify which of the two fields is wrong — that's intentional, for security.",
    'aide_connexion.erreur_check_intro' => "Before trying again, check in order:",
    'aide_connexion.erreur_check_list' => "<b>1.</b> Is the right name selected in the list?<br>\n<b>2.</b> Is the code typed without a space or typo?<br>\n<b>3.</b> Is Caps Lock not left on?",
    'aide_connexion.erreur_contact' => "Still stuck? Contact an administrator to have them check or reset your code — the account may also be deactivated.",
    'aide_connexion.accueil_lede' => "The screen shown right after logging in isn't the same for everyone: it depends on the account used. Two scenarios, each shown below with a real screenshot.",
    'aide_connexion.accueil_maint_h3' => "Maintenance Team: the full GMAO",
