    'aide_connexion.shot_accueil_tuiles_alt' => "GMAO home screen with navigation tiles, administrator view",
    'aide_connexion.shot_accueil_tuiles_cap' => "The GMAO home screen, seen with an administrator account — every tile is accessible.",
    'aide_connexion.accueil_lock_note' => "With a <b>technician</b> account, the tiles reserved for administrators (Preventive, Technician Stats, KPI, Equipment Fleet, User Management) appear <b>greyed out with a lock</b>. That's not an error: those functions simply aren't part of your day-to-day.",
    'aide_connexion.accueil_menu_tip' => "Once on the GMAO screens, a round button top-left (<i class=\"fa-solid fa-bars\"></i>) opens the full side menu at any time, to navigate without going back to the home screen. (The round button you see on this help page just takes you back.)",
    'aide_connexion.accueil_service_h3' => "Other services: the Services Portal",
