    'aide_kpi.carrousel_intro' => "Just below this breakdown bar, a row of 3 dots + a Pause button drives the display of the <b>\"Recurring breakdowns by area\"</b>, <b>\"Recurring breakdowns by equipment\"</b> and <b>\"Monthly breakdown trend\"</b> panels:",
    'aide_kpi.carrousel_li1' => "These 3 panels switch <b>together</b>, automatically, every <b>5 seconds</b>: Curative → Preventive → Project → Curative…",
    'aide_kpi.carrousel_li2' => "The badge shown in each panel's header (e.g. \"Project · Top 15\") always indicates the category currently displayed.",
    'aide_kpi.carrousel_li3' => "Clicking a dot (Curative/Preventive/Project) switches to it immediately and restarts the 5-second timer from that moment.",
    'aide_kpi.carrousel_li4' => "The <b>Pause</b> button stops the automatic cycling to give you time to read a specific category; it becomes <b>Resume</b> to restart the cycle.",
    'aide_kpi.carrousel_p2' => "In \"Recurring breakdowns by area\", clicking a row opens the work order details for that area — <b>filtered on the category currently shown</b> by the carousel (Curative, Preventive or Project depending on what's selected at the moment of the click).",
    'aide_kpi.shot_panneaux_alt' => "Recurring breakdowns by area and by equipment panels",
    'aide_kpi.shot_panneaux_cap' => "\"Recurring breakdowns by area\" and \"Recurring breakdowns by equipment\" (Top 15) — the content shown depends on the carousel's active category described above.",
    'aide_kpi.shot_donut_alt' => "Ring chart of the Top 5 equipment with recurring breakdowns",
    'aide_kpi.shot_donut_cap' => "Clicking the \"Most recurring breakdown\" card: Top 5 equipment (curative + project) + \"Other\", clickable to see an area's detail. This donut is independent of the carousel — it always stays on curative + project combined.",
    'aide_kpi.stats_tech_lede' => "Unlike KPI, this screen <b>has no filter</b>: the three charts are fixed, and you read them by clicking to go further.",
    'aide_kpi.shot_stats_alt' => "The three charts of the Technician Stats screen",
    'aide_kpi.shot_stats_cap' => "Top to bottom: hours trend (last 7 days), breakdown by technician (total cumulative), Curative vs Preventive breakdown.",
    'aide_kpi.stats_li1' => "<b>Intervention hours trend</b>: sum of hours logged per day, over a fixed rolling 7-day window — not configurable from the screen.",
    'aide_kpi.stats_li2' => "<b>Breakdown by Technician</b>: cumulative total of all hours logged <i>since the beginning</i> (no date limit), all ticket statuses combined. Clicking a slice opens the technician's list of interventions.",
    'aide_kpi.stats_li3' => "<b>Curative vs Preventive breakdown</b>: look closely at this card's legend in the screenshot above — see pitfall #4 just below.",
    'aide_kpi.export_p' => "There is <b>no global export</b> (PDF/Excel) of an entire dashboard. The only export possible is individual: opening a ticket's detail from one of the history windows, the <b>\"EXPORT AS PDF\"</b> button generates the report for that specific work order.",
    'aide_kpi.pieges_h2' => "Reading pitfalls — know these before interpreting a number",
    'aide_kpi.pieges_lede' => "These dashboards are reliable, but a few behaviors are worth knowing so you don't misread a number in a meeting.",
    'aide_kpi.pf1_title' => "The \"Recurring breakdowns\" panels change category on their own",
    'aide_kpi.pf1_desc' => "\"Recurring breakdowns by area/equipment\" and \"Monthly breakdown trend\" automatically switch between Curative, Preventive and Project every 5 seconds. Before quoting a number from these panels, check the displayed badge (e.g. \"Project\") — or click Pause to freeze the display on the category you want.",
    'aide_kpi.pf2_title' => "Unvalidated \"Pending\" requests are counted",
    'aide_kpi.pf2_desc' => "Total interventions, Completion rate and the breakdowns also include requests not yet validated by maintenance, which can inflate the apparent volume and lower the displayed completion rate.",
    'aide_kpi.pf3_title' => "A badly filled-in type counts as \"Curative\"",
    'aide_kpi.pf3_desc' => "Only a ticket whose type is exactly \"Preventive\" or \"Project\" is counted as such — everything else (including an empty or misspelled type field) automatically falls into Curative.",
    'aide_kpi.pf4_title' => "The Technician Stats \"Curative vs Preventive\" pie chart is always empty",
    'aide_kpi.pf4_desc' => "This isn't a real lack of data: this feature isn't finished in the current code. Never conclude \"there's never been any preventive maintenance\" from this specific chart — use the Curative/Preventive bar on the KPI screen instead.",
    'aide_kpi.pf5_title' => "Cumulative hours mix all statuses together",
    'aide_kpi.pf5_desc' => "A ticket still \"to do\" on which time has already been logged counts fully in the cumulative hours and in the technician's workload.",
    'aide_kpi.pf6_title' => "The KPI filter's technician list is fixed",
    'aide_kpi.pf6_desc' => "A technician created afterwards won't appear in the KPI screen's \"TECHNICIAN\" dropdown, even though their hours show up correctly in the \"Workload by Technician\" panel.",
    'aide_kpi.pf7_title' => "A technician at 0h disappears, instead of showing \"0h\"",
    'aide_kpi.pf7_desc' => "The \"Workload by Technician\" panel completely hides technicians with no hours logged over the period — being absent from the list doesn't mean \"no data\", but rather \"zero hours\".",
    'aide_kpi.pf8_title' => "Two different time logics between the two screens",
    'aide_kpi.pf8_desc' => "KPI has no default period (full history), while the Technician Stats chart is locked to a non-adjustable rolling 7 days — keep this difference in mind when switching between the two.",
    'aide_kpi.gloss_taux_dt' => "Completion rate",
    'aide_kpi.gloss_taux_dd' => "Percentage of \"done\" tickets out of the filtered set's total.",
    'aide_kpi.gloss_pointage_dt' => "Time entry",
    'aide_kpi.gloss_pointage_dd' => "A line recording time spent by a technician on a ticket — the basis for every hours calculation.",
    'aide_kpi.gloss_panne_dt' => "Most recurring breakdown",
    'aide_kpi.gloss_panne_dd' => "The equipment that comes back most often as curative or project work (breakdowns/breakages) in the filtered set's tickets — routine preventive maintenance isn't counted.",
    'aide_kpi.gloss_chantier_dt' => "Project",
    'aide_kpi.gloss_chantier_dd' => "Third work order category, alongside Curative and Preventive: an installation, modification or improvement project (as opposed to a repaired breakdown or a scheduled check).",
    'aide_kpi.devnote_summary' => "Technical note (admin / dev team)",
    'aide_kpi.devnote_li1' => "<code>stats_tech.php</code>: the <code>\$sql3</code> query (Curative/Preventive breakdown) is commented out in the code and <code>dataTypes</code> is hardcoded to <code>[0, 0]</code> — the corresponding chart will never show data until this is wired up.",
    'aide_kpi.devnote_li2' => "<code>api.php</code> returns all tasks without filtering out the <code>Pending</code> status, including for the KPI/Stats screens — unlike what the partial (but non-functional) filter present in <code>maintenance.php</code> suggests.",

    // --- Additional shared elements ---
    'aide_common.devnote_summary' => "Technical note (admin / dev team)",
    'aide_common.roadmap_title' => "This document keeps growing",
    'aide_common.roadmap_text' => "Find every available and upcoming guide on the <a href=\"aide.php\">Help Center</a>.",
    'aide_common.pill_reserve_admins' => "Admin only",
    'aide_common.oui' => "Yes",
    'aide_common.non' => "No",

    // --- aide_utilisateurs.php ---
    'aide_utilisateurs.page_title_tag' => "Manage Users - GMAO Help",
    'aide_utilisateurs.hero_tagline' => "Create an account, change a password, activate or deactivate access.",
    'aide_utilisateurs.pill_version' => "Version <b>1.0</b>",
    'aide_utilisateurs.pill_updated' => "Updated on <b>20/08/2026</b>",
    'aide_utilisateurs.pill_ecran' => "Screen covered <b>User Management</b>",
    'aide_utilisateurs.toc_vue_ensemble' => "Overview",
    'aide_utilisateurs.toc_roles' => "Available roles",
    'aide_utilisateurs.toc_creer' => "Create an account",
    'aide_utilisateurs.toc_modifier' => "Edit a profile",
    'aide_utilisateurs.toc_mdp' => "Change a password",
    'aide_utilisateurs.toc_pin' => "The personal PIN code",
    'aide_utilisateurs.toc_activer' => "Activate / deactivate an account",
    'aide_utilisateurs.toc_supprimer' => "Delete an account",
    'aide_utilisateurs.toc_securite' => "Security, what you should know",
    'aide_utilisateurs.toc_droits' => "Who can do what",
    'aide_utilisateurs.toc_astuces' => "Tips & pitfalls",
    'aide_utilisateurs.toc_glossaire' => "Glossary",
    'aide_utilisateurs.vue_ensemble_lede' => "<b>User Management</b> centralizes every account in the application: the maintenance team that uses the GMAO daily, services' \"portal\" accounts, and staff identified by a simple PIN code. The page groups them into three blocks.",
    'aide_utilisateurs.case1_h4' => "Maintenance Team",
    'aide_utilisateurs.case1_p' => "<b>Admin</b> and <b>technician</b> accounts — full access to the GMAO.",
    'aide_utilisateurs.case2_h4' => "Services Portal Access",
    'aide_utilisateurs.case2_p' => "Service accounts (Production, Quality...) protected by a password, granting access to the simplified requester portal.",
    'aide_utilisateurs.case3_h4' => "Staff & Operators",
    'aide_utilisateurs.case3_p' => "Grouped by service, identified by a PIN code rather than a password — these are the \"requesters\" of the work request portal.",
    'aide_utilisateurs.roles_tbl_role' => "Role",
    'aide_utilisateurs.roles_tbl_donne' => "What it grants",
    'aide_utilisateurs.role1_nom' => "Maintenance Administrator",
    'aide_utilisateurs.role1_desc' => "Full access to the GMAO, including this page.",
    'aide_utilisateurs.role2_nom' => "Maintenance Technician",
    'aide_utilisateurs.role2_desc' => "Access to the GMAO, without user management or certain admin pages.",
    'aide_utilisateurs.role3_nom' => "A service (e.g. Production, Quality...)",
    'aide_utilisateurs.role3_desc' => "Access to the simplified requester portal — not to the GMAO.",
    'aide_utilisateurs.roles_tip' => "The list of <b>services</b> offered in the \"Service / Assignment\" dropdown isn't fixed — it comes from <b>Settings &gt; Services</b>. Adding or renaming a service there immediately updates the choices available here.",
    'aide_utilisateurs.creer_lede' => "<b>\"NEW USER / REQUESTER\"</b> button at the top of the page. The window offers two modes.",
    'aide_utilisateurs.mode1_tag' => "Mode 1",
    'aide_utilisateurs.mode1_h3' => "Portal / Maintenance Access",
    'aide_utilisateurs.mode1_p' => "For an account protected by <b>password</b>: maintenance team, or a service needing dedicated portal access. The <b>\"Password\"</b> field is required in this mode.",
    'aide_utilisateurs.mode2_tag' => "Mode 2",
    'aide_utilisateurs.mode2_h3' => "Employee / Operator",
    'aide_utilisateurs.mode2_p' => "For a simple requester identified by <b>PIN code</b>: the first name field appears, and the personal code becomes optional (\"Leave blank = auto-memorize\", see below).",
    'aide_utilisateurs.creer_tbl_champ' => "Field",
    'aide_utilisateurs.creer_tbl_detail' => "Detail",
    'aide_utilisateurs.champ1_nom' => "Username (or Last name)",
    'aide_utilisateurs.champ1_d' => "Required, must be unique.",
    'aide_utilisateurs.champ2_nom' => "Service / Assignment",
    'aide_utilisateurs.champ2_d' => "Required — a service, or \"Maintenance Technician\" / \"Maintenance Administrator\".",
    'aide_utilisateurs.champ3_nom' => "Function / Position",
    'aide_utilisateurs.champ3_d' => "Free text, optional.",
    'aide_utilisateurs.champ4_nom' => "Email / Phone",
    'aide_utilisateurs.champ4_d' => "Optional.",
    'aide_utilisateurs.champ5_nom' => "Password (Portal mode)",
    'aide_utilisateurs.champ5_d' => "Required in this mode.",
    'aide_utilisateurs.champ6_nom' => "First name (Employee mode)",
    'aide_utilisateurs.champ6_d' => "Optional.",
    'aide_utilisateurs.champ7_nom' => "PIN code (Employee mode)",
    'aide_utilisateurs.champ7_d' => "Optional — see the dedicated section.",
    'aide_utilisateurs.creer_footer' => "The created account is <b>always active</b> from the start. If the username already exists: \"Error: This username already exists.\"",
    'aide_utilisateurs.modifier_lede' => "Click any user card to open its full profile. The fields shown adapt depending on whether it's a \"portal\" account (password) or \"employee\" account (PIN): Service/Role, Function, Email, Phone, and depending on the case, password or First name + PIN code, plus the account status (active/deactivated).",
    'aide_utilisateurs.modifier_p2' => "<b>\"UPDATE\"</b> button to save, <b>trash can</b> icon to delete, <b>\"CLOSE\"</b> to exit without changing anything.",
    'aide_utilisateurs.mdp_lede' => "There's no separate \"Reset\" button: open the account's profile, enter the new value in <b>\"New Password (Portal)\"</b>, then \"UPDATE\".",
    'aide_utilisateurs.mdp_tip' => "The field is <b>optional</b> when editing: if you leave it blank (\"Leave blank if unchanged\"), the existing password isn't touched.",
    'aide_utilisateurs.pin_lede' => "This is the code employees/operators enter to be recognized in the work request portal.",
    'aide_utilisateurs.pin_tip' => "<b>Auto-memorize:</b> if you create an employee account without a PIN code, that's not a blocker. The first time that person enters a code in the request portal, the application <b>automatically saves it</b> as their definitive personal code. You can then view or change it here at any time.",
    'aide_utilisateurs.pin_warn' => "Unlike the password (always masked and encrypted), the <b>PIN code is shown in plain text</b> — in the edit profile and as a red badge directly on the employee's mini-card. This is a deliberately lighter security level, suited to a simple identification code, not a real password.",
    'aide_utilisateurs.activer_lede' => "In the edit profile, the <b>\"Account status\"</b> field offers two values: <b>\"[ V ] ACTIVE ACCOUNT (Access authorized)\"</b> or <b>\"[ X ] DEACTIVATED ACCOUNT (Access blocked)\"</b>.",
    'aide_utilisateurs.activer_warn' => "A deactivated account can no longer log in at all (message \"Access denied: This account has been deactivated.\"), but stays visible here to be reactivated later. <b>No visual badge</b> flags a deactivated account directly on the list's cards — you have to open each profile to check its status.",
    'aide_utilisateurs.supprimer_lede' => "Trash can icon in the edit profile, with a simple confirmation.",
    'aide_utilisateurs.supprimer_warn' => "<b>Permanent deletion</b>, with no check of related data. History (work orders, log, past schedules) stays displayed with the old name, but the account no longer exists — it can no longer log in, and nothing can be reassigned to it anymore. Nothing prevents an administrator from demoting or deleting <b>themselves</b> either: there's no \"last admin\" protection.",
    'aide_utilisateurs.securite_li1' => "<b>The password is always encrypted</b> before being stored — never readable, by you or anyone else.",
    'aide_utilisateurs.securite_li2' => "<b>The PIN code, however, is stored and displayed in plain text</b> — never use it as a real sensitive password.",
    'aide_utilisateurs.securite_li3' => "<b>No action on this page is logged</b>: creating, editing, deactivating or deleting an account leaves no trace in the <a href=\"aide_logs.php\">Activity Log</a>.",
    'aide_utilisateurs.securite_li4' => "A technician's <b>annual hours target</b> (used in the Schedule) isn't set here — it's changed directly from that person's <a href=\"aide_planning.php\">Annual Schedule</a>.",
    'aide_utilisateurs.droits_action' => "Action",
    'aide_utilisateurs.droits_tech' => "Technician",
    'aide_utilisateurs.droits_admin' => "Admin",
    'aide_utilisateurs.droits1' => "Access the page",
    'aide_utilisateurs.droits2' => "Create / edit / delete an account",
    'aide_utilisateurs.droits3' => "Change a password or PIN",
    'aide_utilisateurs.astuces_li1' => "<b>Remember to check the active/inactive status</b> before assuming a blocked account is visible at a glance — it isn't.",
    'aide_utilisateurs.astuces_li2' => "<b>Leave the PIN code blank when creating</b> a new employee if you don't know it: it will memorize itself as soon as they make their first request.",
    'aide_utilisateurs.astuces_li3' => "<b>Don't look for the annual hours target here</b> — it's in the Schedule.",
    'aide_utilisateurs.astuces_li4' => "<b>Think before deleting</b> an account with significant history: deactivating it instead is reversible.",
    'aide_utilisateurs.gloss1_dt' => "Portal account",
    'aide_utilisateurs.gloss1_dd' => "Account protected by a password (maintenance team or service).",
    'aide_utilisateurs.gloss2_dt' => "Employee / operator account",
    'aide_utilisateurs.gloss2_dd' => "Account identified by a PIN code, used on the request portal side.",
    'aide_utilisateurs.gloss3_dt' => "PIN code",
    'aide_utilisateurs.gloss3_dd' => "Personal numeric code, stored in plain text, identifying a requester.",
    'aide_utilisateurs.gloss4_dt' => "Auto-memorize",
    'aide_utilisateurs.gloss4_dd' => "The PIN sets itself automatically the first time the employee enters one, if it wasn't already set.",
    'aide_utilisateurs.devnote_intro' => "Points noted while reviewing the code, worth keeping in mind on the admin side:",
    'aide_utilisateurs.devnote_li1' => "The password field is an <code>&lt;input type=\"text\"&gt;</code> in both modals (not <code>type=\"password\"</code>) — so the input isn't masked on screen.",
    'aide_utilisateurs.devnote_li2' => "No call to <code>ajouterLog()</code> in this file: unlike <code>login.php</code> or <code>parametres.php</code>, no account-administration action is tracked in <code>logs.php</code>.",
    'aide_utilisateurs.devnote_li3' => "Deletion (<code>DELETE FROM utilisateurs</code>) checks no dependency — tickets/logs reference the user by their <code>username</code> as free text, not by foreign key, so nothing technically blocks the deletion.",
    'aide_utilisateurs.devnote_li4' => "No \"last admin\" protection, nor \"can't edit yourself\".",

    // --- aide_logs.php ---
    'aide_logs.page_title_tag' => "View the Activity Log - GMAO Help",
    'aide_logs.hero_tagline' => "Who did what, and when — the history of important GMAO actions.",
    'aide_logs.pill_version' => "Version <b>1.0</b>",
    'aide_logs.pill_updated' => "Updated on <b>20/08/2026</b>",
    'aide_logs.pill_ecran' => "Screen covered <b>Activity Log</b>",
    'aide_logs.toc_vue_ensemble' => "Overview",
    'aide_logs.toc_lire' => "Reading a log entry",
    'aide_logs.toc_quoi' => "What is (and isn't) logged",
    'aide_logs.toc_filtrer' => "Filter and search",
    'aide_logs.toc_limites' => "Limits to know about",
    'aide_logs.toc_vider' => "Clear the log",
    'aide_logs.toc_droits' => "Who can do what",
    'aide_logs.toc_astuces' => "Tips & pitfalls",
    'aide_logs.toc_glossaire' => "Glossary",
    'aide_logs.vue_ensemble_lede' => "The <b>Activity Log</b> displays, as a table, the history of important actions taken in the GMAO: who did what, and when. This is the tool to check when in doubt about \"who changed that?\" or \"when was this machine added?\".",
    'aide_logs.vue_ensemble_lock' => "This page is <b>entirely reserved for administrators</b>. A technician or other maintenance team member has no access to it and doesn't even see the tile on the home screen.",
    'aide_logs.lire_lede' => "Each row in the table corresponds to an event, with 4 columns.",
    'aide_logs.col_colonne' => "Column",
    'aide_logs.col_contenu' => "Content",
    'aide_logs.col1_nom' => "Date & Time",
    'aide_logs.col1_desc' => "Exact timestamp of the action, in <code>dd/mm/yyyy hh:mm</code> format (e.g. <code>20/08/2026 14:32</code>).",
    'aide_logs.col2_nom' => "User",
    'aide_logs.col2_desc' => "The name of the logged-in person who performed the action.",
    'aide_logs.col3_nom' => "Action",
    'aide_logs.col3_desc' => "A short label shown in a colored badge (see below), e.g. \"Add Machine\", \"Settings\", \"Login\".",
    'aide_logs.col4_nom' => "Details",
    'aide_logs.col4_desc' => "A free-text description detailing the action, e.g. \"Added machine: Conveyor B12\".",
    'aide_logs.badges_intro' => "The \"Action\" badge's color depends on keywords detected in its label:",
    'aide_logs.badge_add_label' => "Add / creation",
    'aide_logs.badge_add_suffix' => "— green badge",
    'aide_logs.badge_edit_label' => "Edit",
    'aide_logs.badge_edit_suffix' => "— blue badge",
    'aide_logs.badge_delete_label' => "Deletion",
    'aide_logs.badge_delete_suffix' => "— red badge",
    'aide_logs.badge_login_label' => "Login",
    'aide_logs.badge_login_suffix' => "— orange badge",
    'aide_logs.badge_default_label' => "Other",
    'aide_logs.badge_default_suffix' => "— grey badge, for any event that doesn't match any of the cases above",
    'aide_logs.lire_footer' => "Entries are sorted <b>from most recent to oldest</b>, with no way to change this order.",
    'aide_logs.quoi_lede' => "The log doesn't cover the whole application — only certain actions, deemed important to track, are recorded there.",
    'aide_logs.trace_tag' => "Tracked",
    'aide_logs.trace_h3' => "What appears in the log",
    'aide_logs.trace_li1' => "Logins to the application",
    'aide_logs.trace_li2' => "Machine additions and edits (Equipment Fleet)",
    'aide_logs.trace_li3' => "Suggested improvement ideas and their handling",
    'aide_logs.trace_li4' => "Schedule imports",
    'aide_logs.trace_li5' => "Any change made from the <b>Settings</b> page: categories, statuses, home tiles, schedule styling, annual targets, etc.",
    'aide_logs.non_trace_tag' => "Not tracked",
    'aide_logs.non_trace_h3' => "What doesn't appear",
    'aide_logs.non_trace_li1' => "Creating, taking charge of, or closing a work order (BI)",
    'aide_logs.non_trace_li2' => "Schedule entries (shifts, leave, hours...)",
    'aide_logs.non_trace_li3' => "<b>Logouts</b> — only the login is recorded",
    'aide_logs.non_trace_li4' => "Clearing the log itself (see below)",
    'aide_logs.quoi_warn' => "Don't rely on this log to retrace a work order's or a time entry's history — use the relevant work order's detail sheet instead (see <a href=\"aide_ot.php\">the work order guide</a>), which keeps its own history of statuses and reports.",
    'aide_logs.filtrer_lede' => "Three combinable filters let you quickly find a specific entry. They act instantly, without reloading the page.",
    'aide_logs.shot_filtres_alt' => "Activity Log filter bar: user, action, search",
    'aide_logs.shot_filtres_cap' => "The filter bar at the top of the table, and the RESET button to clear everything.",
    'aide_logs.case_user_h4' => "User",
    'aide_logs.case_user_p' => "Type a name (or part of a name) to keep only that person's entries.",
    'aide_logs.case_action_h4' => "Action",
    'aide_logs.case_action_p' => "Dropdown: All actions / Additions / Creations / Edits / Deletions / Logins.",
    'aide_logs.case_recherche_h4' => "Search",
    'aide_logs.case_recherche_p' => "Searches for a keyword in the Details column only (e.g. a machine's name).",
    'aide_logs.filtrer_footer' => "The <b>\"RESET\"</b> button clears all three filters at once and shows every loaded row again.",
    'aide_logs.limites_li1' => "<b>Only the 200 most recent entries</b> are loaded and shown. Beyond that, older history stays stored in the database but no longer appears on screen.",
    'aide_logs.limites_li2' => "<b>No export</b> (PDF, Excel, CSV) is available from this page.",
    'aide_logs.limites_li3' => "<b>No automatic purge</b> by age: entries accumulate indefinitely until a manual clear (see below).",
    'aide_logs.vider_lede' => "The red <b>\"CLEAR THE LOG\"</b> button, top right, deletes <b>the entire</b> history.",
    'aide_logs.vider_step1_title' => "Click \"CLEAR THE LOG\"",
    'aide_logs.vider_step1_desc' => "A confirmation window opens: \"Clear the log? — Are you sure you want to clear the ENTIRE log history? This action is permanent and irreversible.\"",
    'aide_logs.vider_step2_title' => "Confirm with \"CLEAR EVERYTHING\"",
    'aide_logs.vider_step2_desc' => "All entries are deleted immediately. The \"CANCEL\" button closes the window without doing anything.",
    'aide_logs.vider_warn' => "<b>Permanent action:</b> once confirmed, there's no way to recover the erased history — no automatic backup, no trash bin. And ironically, this total deletion isn't itself logged: after a clear, there's no trace left of who cleared the log or when.",
    'aide_logs.droits_action' => "Action",
    'aide_logs.droits_tech' => "Technician",
    'aide_logs.droits_admin' => "Admin",
    'aide_logs.droits1' => "Access the page",
    'aide_logs.droits2' => "Filter / search",
    'aide_logs.droits3' => "Clear the log",
    'aide_logs.astuces_li1' => "<b>Don't look for logouts</b>: they're never recorded, only the login is.",
    'aide_logs.astuces_li2' => "<b>Don't look for a work order's or a time entry's history</b> here — that's not what this log tracks. Refer to the relevant work order's sheet instead.",
    'aide_logs.astuces_li3' => "<b>Think before clearing the log</b>: it's irreversible, and the clearing action itself leaves no trace behind.",
    'aide_logs.astuces_li4' => "<b>Combine filters</b> to quickly find a specific entry, for example \"User = Dupont\" + \"Action = Edits\" to see everything they've recently changed.",
    'aide_logs.gloss1_dt' => "Activity Log",
    'aide_logs.gloss1_dd' => "The table listing important actions taken in the GMAO, with date, author and details.",
    'aide_logs.gloss2_dt' => "Action",
    'aide_logs.gloss2_dd' => "The type of recorded event (addition, edit, deletion, login...).",
    'aide_logs.gloss3_dt' => "Details",
    'aide_logs.gloss3_dd' => "The free-text description accompanying each log entry.",
    'aide_logs.gloss4_dt' => "Purge / clear",
    'aide_logs.gloss4_dd' => "The total, irreversible deletion of the entire log history.",
    'aide_logs.devnote_intro' => "Points noted while reviewing the code, worth keeping in mind on the admin side:",
    'aide_logs.devnote_li1' => "Logging (<code>ajouterLog()</code> in <code>db.php</code>) silently swallows any SQL error (empty try/catch) \"so as not to block the application\" — a log write can therefore fail without any alert signaling it.",
    'aide_logs.devnote_li2' => "Creating/closing work orders and Schedule entries don't call <code>ajouterLog()</code>: only Equipment Fleet, Ideas, Schedule Import, Settings and login do.",
    'aide_logs.devnote_li3' => "Clearing the log (<code>logs.php?action=clear</code>) is triggered by a simple GET link protected only by the session role check — no CSRF token. Worth hardening if this page is ever exposed more widely.",

    // --- aide_parametres.php ---
    'aide_parametres.page_title_tag' => "Configure Settings - GMAO Help",
    'aide_parametres.hero_tagline' => "The settings hub for the whole GMAO — 7 tabs, from the company name to the schedule colors.",
    'aide_parametres.pill_version' => "Version <b>1.0</b>",
    'aide_parametres.pill_updated' => "Updated on <b>20/08/2026</b>",
    'aide_parametres.pill_ecran' => "Screen covered <b>Settings</b>",
    'aide_parametres.toc_vue_ensemble' => "Overview",
    'aide_parametres.toc_general' => "General",
    'aide_parametres.toc_types' => "Equipment types",
    'aide_parametres.toc_services' => "Services",
    'aide_parametres.toc_categories' => "Preventive categories",
    'aide_parametres.toc_statuts' => "Statuses & priorities",
    'aide_parametres.toc_planning' => "Schedule",
    'aide_parametres.toc_tuiles' => "Home tiles",
    'aide_parametres.toc_droits' => "Who can do what",
    'aide_parametres.toc_astuces' => "Tips & pitfalls",
    'aide_parametres.toc_glossaire' => "Glossary",
    'aide_parametres.vue_ensemble_lede' => "<b>Settings</b> centralizes every GMAO configuration, spread across 7 tabs. This is where you populate the lists used everywhere else — equipment types, services, statuses, schedule colors, home tiles.",
    'aide_parametres.vue_ensemble_tip' => "Most lists on this page are reordered with <b>Up / Down arrows</b> on each row (no drag-and-drop here), and offer <b>no search</b> — you browse the full list visually.",
    'aide_parametres.general_h2' => "General tab",
    'aide_parametres.general_lede' => "The company name and logo shown across the whole application header.",
    'aide_parametres.shot_general_alt' => "Settings' General tab with all 7 tabs visible",
    'aide_parametres.shot_general_cap' => "The 7 Settings tabs, here on \"General\": the application's displayed name and logo.",
    'aide_parametres.tbl_champ' => "Field",
    'aide_parametres.tbl_detail' => "Detail",
    'aide_parametres.general_champ1_nom' => "Displayed company / GMAO name",
    'aide_parametres.general_champ1_d' => "Free text, required.",
    'aide_parametres.general_champ2_nom' => "Logo",
    'aide_parametres.general_champ2_d' => "PNG, JPG, SVG or WEBP only. Replaces the header and menu logo.",
    'aide_parametres.types_h2' => "Equipment types tab",
    'aide_parametres.types_lede' => "The list used to classify <a href=\"aide_parc_machine.php\">Equipment Fleet</a> machines (Mechanical, Electrical, Cold...).",
    'aide_parametres.types_step1_title' => "Add",
    'aide_parametres.types_step1_desc' => "Name + an icon chosen from a grid of 20.",
    'aide_parametres.types_step2_title' => "Edit",
    'aide_parametres.types_step2_desc' => "Renaming a type <b>automatically reclassifies</b> every machine already using it — nothing breaks.",
    'aide_parametres.types_step3_title' => "Delete",
    'aide_parametres.types_step3_desc' => "<b>Blocked</b> if at least one machine still uses this type: \"Cannot delete: this type is still used by at least one machine.\"",
    'aide_parametres.services_h2' => "Services tab",
    'aide_parametres.services_lede' => "The company's list of services (Production, HR, Quality...), used for \"requester\" accounts' role in <a href=\"aide_utilisateurs.php\">User Management</a>.",
    'aide_parametres.tbl_action' => "Action",
    'aide_parametres.tbl_regle' => "Rule",
    'aide_parametres.services_row1_action' => "Add",
    'aide_parametres.services_row1_regle' => "A single field: the name. An internal technical key is generated automatically and never changes again.",
    'aide_parametres.services_row2_action' => "Edit",
    'aide_parametres.services_row2_regle' => "Only the displayed label can change, not the technical key.",
    'aide_parametres.services_row3_action' => "Delete",
    'aide_parametres.services_row3_regle' => "<b>Blocked</b> if at least one user account has this service as its role.",
    'aide_parametres.categories_h2' => "Preventive categories tab",
    'aide_parametres.categories_lede' => "The categories used to classify preventive maintenance plans (Process, Quality, Regulatory, Daily by default).",
    'aide_parametres.categories_p' => "Add/edit form: Name, Description (shown on the Preventive module's home tile), Icon (grid of 20) and Color (30 preset colors + a picker for any custom shade).",
    'aide_parametres.categories_warn' => "Double protection on deletion: <b>impossible to go below 1 remaining category</b>, and <b>blocked</b> if the category is still used by at least one preventive rule.",
    'aide_parametres.statuts_h2' => "Statuses & priorities tab",
    'aide_parametres.statuts_lede' => "Renames and recolors how statuses (Pending, To do, In progress, Done, Refused) and priorities (Normal, Urgent) are displayed <b>across the whole application</b>.",
    'aide_parametres.statuts_lock' => "This is a <b>closed</b> set: there's neither an \"Add\" nor a \"Delete\" button on this tab. Only the <b>label</b> and <b>color</b> of each existing status/priority can be changed — the value actually stored on each intervention itself never changes. It's purely visual styling.",
    'aide_parametres.statuts_tip' => "As long as you only change the <b>color</b> (the label field stays as it was pre-filled), the display keeps following each user's chosen language automatically (FR/EN/NL). As soon as you <b>type new text</b> into the label, that text replaces the automatic translation and is shown identically in every language.",
    'aide_parametres.planning_h2' => "Schedule tab",
    'aide_parametres.planning_lede' => "The richest of the 7 tabs: <a href=\"aide_planning.php\">Schedule</a> styling, annual hour targets, and import/reset tools.",
    'aide_parametres.shot_planning_alt' => "Settings' Schedule tab: shift and event color dots",
    'aide_parametres.shot_planning_cap' => "The Schedule tab: each shift/event has its color dot and Edit button — the list itself is closed.",
    'aide_parametres.planning_h3_listes' => "Shifts, Events, On-call",
    'aide_parametres.planning_listes_p' => "Three closed lists (same rules as Statuses & priorities: only label and color can change, no adding/removing):",
    'aide_parametres.planning_li_postes' => "<b>Shifts</b>: Morning, Afternoon, Night, Full day, Public holiday.",
    'aide_parametres.planning_li_evenements' => "<b>Events</b>: Half paid leave, Paid leave, Sick leave, RTT, Rest day.",
    'aide_parametres.planning_li_astreintes' => "<b>On-call</b>: On-call, Cold on-call.",
    'aide_parametres.planning_h3_objectifs' => "Annual hour targets",
    'aide_parametres.planning_objectifs_p' => "A list of every technician with their current hour target (1607h by default). Adjustable individually — useful for part-time. This is the same setting also reachable directly from a technician's <a href=\"aide_planning.php\">Annual Schedule</a>.",
    'aide_parametres.planning_h3_import' => "Schedule import and reset",
    'aide_parametres.reset_planning_tag' => "Destructive",
    'aide_parametres.reset_planning_h3' => "Reset the schedule",
    'aide_parametres.reset_planning_p' => "Deletes <b>everything</b> that was imported (shifts, on-call, hours, notes), across every period. Irreversible.",
    'aide_parametres.reset_heures_tag' => "Destructive, more targeted",
    'aide_parametres.reset_heures_h3' => "Reset the hours",
    'aide_parametres.reset_heures_p' => "Resets only the <b>hours</b> to zero, keeping shifts, on-call and notes already shown. Also irreversible, but far less radical.",
    'aide_parametres.planning_warn' => "Don't confuse the two buttons: \"Reset the schedule\" erases everything, \"Reset the hours\" only touches hours. Both are <b>permanent</b>, with no automatic backup.",
    'aide_parametres.tuiles_h2' => "Home tiles tab",
    'aide_parametres.tuiles_lede' => "Customizes the title, description and color of each tile shown on the home page.",
    'aide_parametres.tuiles_fixes_h4' => "The 13 fixed tiles",
    'aide_parametres.tuiles_fixes_p' => "Entry & History, Schedule, Subcontractors, Preventive, Technician Stats, KPI, Equipment Fleet, User Management, Received Ideas, Settings, Activity Log, Services Portal, Help. Each has a default title and color, replaceable here.",
    'aide_parametres.dossiers_h4' => "My folders",
    'aide_parametres.dossiers_p' => "The personal folders <b>you</b> created on your own home screen (\"+ Add\" button from the home page, not from Settings). This tab only lets you <b>edit</b> an existing folder — title, description, icon, color — and it's specific to your account, invisible to other admins.",
    'aide_parametres.tuiles_tip' => "Any customization saved here <b>replaces</b> a tile's default title/description/color, for every user of the application.",
    'aide_parametres.droits_action' => "Action",
    'aide_parametres.droits_tech' => "Technician",
    'aide_parametres.droits_admin' => "Admin",
    'aide_parametres.droits1' => "Access the page",
    'aide_parametres.droits2' => "Edit any tab",
    'aide_parametres.astuces_li1' => "<b>Statuses, priorities, shifts, events and on-call form closed lists</b>: you can only rename/recolor them, never add or remove.",
    'aide_parametres.astuces_li2' => "<b>Renaming an equipment type or a status breaks nothing</b> — machines and interventions already classified follow automatically.",
    'aide_parametres.astuces_li3' => "<b>Double-check which of the two schedule buttons you click</b>: \"hours\" (targeted) or \"schedule\" (erase everything) — both are irreversible.",
    'aide_parametres.astuces_li4' => "<b>There's no search</b> on this page: for a long list (many types or categories), you have to scroll through it manually.",
    'aide_parametres.astuces_li5' => "<b>A preventive category can never drop to zero</b> — at least one will always remain, even if unused.",
    'aide_parametres.gloss1_dt' => "Styling",
    'aide_parametres.gloss1_dd' => "The label and color shown for a status, a priority or a schedule cell — purely visual, without changing the actual stored data.",
    'aide_parametres.gloss2_dt' => "Closed set",
    'aide_parametres.gloss2_dd' => "A list whose items are fixed (no adding/removing possible), only their name and color are adjustable.",
    'aide_parametres.gloss3_dt' => "Tile",
    'aide_parametres.gloss3_dd' => "One of the clickable blocks on the home page, each leading to a GMAO function.",
    'aide_parametres.gloss4_dt' => "Annual target",
    'aide_parametres.gloss4_dd' => "The number of hours a technician must reach over the annualization period, adjustable here or from the Schedule.",
    'aide_parametres.devnote_intro' => "Points noted while reviewing the code, worth keeping in mind on the admin side:",
    'aide_parametres.devnote_li1' => "The account <code>Florent</code> is explicitly excluded from the list of adjustable annual hour targets (hardcoded exclusion in the code).",
    'aide_parametres.devnote_li2' => "The Tiles tab's text states \"the icon can't be changed here\" for fixed tiles, but the modal and the server-side <code>edit_tuile</code> handler do accept and persist an icon change — a text/behavior mismatch to either fix or accept.",
    'aide_parametres.devnote_li3' => "The previous logo file is never deleted from disk on replacement (accumulating <code>logo_&lt;timestamp&gt;.&lt;ext&gt;</code> files in <code>img/</code>).",
    'aide_parametres.devnote_li4' => "Every successful change on this page is logged (<code>ajouterLog</code>, action \"Settings\"), visible in the <a href=\"aide_logs.php\">Activity Log</a>.",

    // --- aide_preventif.php ---
    'aide_preventif.page_title_tag' => "Preventive & Schedule - GMAO Help",
    'aide_preventif.hero_tagline' => "Schedule a maintenance plan, understand its automatic work order generation, and read the weekly schedule.",
    'aide_preventif.pill_version' => "Version <b>1.0</b>",
    'aide_preventif.pill_updated' => "Updated on <b>08/08/2026</b>",
    'aide_preventif.pill_ecrans' => "Screens covered <b>Preventive</b> & <b>Schedule</b>",
    'aide_preventif.toc_vue_ensemble' => "Overview & access",
    'aide_preventif.toc_liste' => "The rule list",
    'aide_preventif.toc_creer' => "Create a preventive rule",
    'aide_preventif.toc_travaux_divers' => "The \"Winter Works\" tab",
    'aide_preventif.toc_generation' => "From rule to work order",
    'aide_preventif.toc_gestion' => "Edit, pause, delete",
    'aide_preventif.toc_planning' => "Read & use the Schedule",
    'aide_preventif.toc_astuces' => "Tips & pitfalls",
    'aide_preventif.toc_glossaire' => "Glossary",
    'aide_preventif.vue_ensemble_lede' => "Two complementary screens: <b>Preventive</b> to schedule recurring checks (lubrication, regulatory inspections, checks…), and <b>Schedule</b> to see who does what, day by day.",
    'aide_preventif.tbl_ecran' => "Screen",
    'aide_preventif.tbl_qui' => "Who can access it",
    'aide_preventif.tbl_pourquoi' => "What for",
    'aide_preventif.row_preventif_ecran' => "Preventive",
    'aide_preventif.row_preventif_pourquoi' => "Create, edit, pause or delete a preventive maintenance rule.",
    'aide_preventif.row_planning_ecran' => "Schedule",
    'aide_preventif.row_planning_pourquoi' => "View and reorganize the week's tasks by technician.",
    'aide_preventif.vue_ensemble_lock' => "If you're a technician, the \"Preventive\" tab doesn't even appear in your menu — that's normal, only maintenance/administration schedules the plans. You do see and use the Schedule normally, though.",
    'aide_preventif.liste_lede' => "The Preventive screen shows every existing plan, with its frequency and due date.",
    'aide_preventif.shot_liste_alt' => "List of preventive maintenance rules with counters and filters",
    'aide_preventif.shot_liste_cap' => "At the top: counters (active rules, overdue, coming due soon). Filter chips: All / Overdue / Soon / Up to date / Paused.",
    'aide_preventif.liste_li1' => "Clicking a row opens the rule's detail sheet (read-only, with an \"Edit\" button).",
    'aide_preventif.liste_li2' => "The <b>\"Printable register\"</b> button generates a printable view of the entire preventive program.",
    'aide_preventif.liste_li3' => "A rule's <b>\"History\"</b> button lists every work order already generated from it.",
    'aide_preventif.creer_lede' => "The <b>\"NEW RULE\"</b> button opens a 4-step wizard.",
    'aide_preventif.creer_tip' => "For a one-off request (just once, no recurrence), don't use this wizard: the <b>\"To preventive\"</b> button in the <a href=\"aide_ot.php#portes\">validation gateway</a> adds it directly to the <a href=\"#travaux-divers\">\"Winter Works\"</a> tab below, without creating a rule.",
    'aide_preventif.step1_title' => "What & When",
    'aide_preventif.step1_desc' => "Operation type, priority, then the <b>scheduling mode</b>: either a <b>frequency in days</b> (daily, weekly, 15 days, monthly, quarterly, half-yearly, yearly), or fixed <b>days of the week</b> (Monday to Friday). Add the estimated duration and, if needed, a hard deadline and an early alert.",
    'aide_preventif.step2_title' => "Location",
    'aide_preventif.step2_desc' => "Same cascade as for a standard work order: Plant → Area → Line → Zone → Equipment. The machine must exist in the Equipment Fleet.",
    'aide_preventif.step3_title' => "Impact & Team",
    'aide_preventif.step3_desc' => "Impact on production (none, total stop, reduced rate, quality impact, safety risk), stop duration, reporter, and above all the <b>assigned technician</b> — they'll automatically receive the generated work orders on their schedule. Alternative: the <b>\"Auto-assign to the Morning shift technician\"</b> checkbox ignores the fixed assignee and picks, at each generation, whoever is on the \"Morning\" shift that day in the <a href=\"planning.php\">Schedule</a> — handy for a task that should always fall to whoever is present in the morning, regardless of who that is.",
    'aide_preventif.step4_title' => "Details",
    'aide_preventif.step4_desc' => "Precise description of the operation (required), identified cause, parts used, comments, then a summary before confirming.",
    'aide_preventif.shot_e1_alt' => "New preventive rule wizard, step 1 What and When",
    'aide_preventif.shot_e1_cap' => "Step 1 — What & When",
    'aide_preventif.shot_e2_alt' => "New preventive rule wizard, step 2 Location",
    'aide_preventif.shot_e2_cap' => "Step 2 — Location",
    'aide_preventif.shot_e3_alt' => "New preventive rule wizard, step 3 Impact and Team",
    'aide_preventif.shot_e3_cap' => "Step 3 — Impact & Team",
    'aide_preventif.shot_e4_alt' => "New preventive rule wizard, step 4 Details and summary",
    'aide_preventif.shot_e4_cap' => "Step 4 — Details & summary",
    'aide_preventif.creer_warn' => "Without an <b>assigned technician</b> set at step 3 — or if \"Auto morning\" is checked but nobody is on the Morning shift that day —, work orders generated by this rule <b>won't appear on the Schedule</b> (they'll only be visible in the regular ticket lists). Always remember to assign a technician if you want the task to be scheduled.",
    'aide_preventif.travaux_lede' => "On a category's page, a second tab next to \"Automatic rules\": a list of <b>one-off</b> tasks to check off, with no frequency or automatic BI generation — for anything that doesn't need to recur every year.",
    'aide_preventif.travaux_tip' => "A task ends up here two ways: added manually via <b>\"+ Add a task\"</b>, or transferred from a pending request in the <a href=\"aide_ot.php#portes\">validation gateway</a> (\"To preventive\" button).",
    'aide_preventif.travaux_champs_title' => "A task's fields",
    'aide_preventif.travaux_champs_desc' => "Equipment, description, <b>reported by</b> (maintenance team or service), <b>assignee(s)</b> — checkboxes for the team, several people possible, plus a free-text line for seasonal production reinforcement without a GMAO account —, planned date and priority (1 to 4, 1 being the most urgent).",
    'aide_preventif.travaux_statut_title' => "Status",
    'aide_preventif.travaux_statut_desc' => "A clickable badge per task: each click advances <b>To do → In progress → Done</b> (then back to To do). Completed tasks turn green and the most recently checked ones move to the top of their group.",
    'aide_preventif.travaux_recherche_title' => "Search & filters",
    'aide_preventif.travaux_recherche_desc' => "Search bar (equipment, task, assignee), Assignee and Priority filters, and the All / To do / In progress / Done tabs. The Equipment, Assignee, Date and Priority columns sort on a click of their header.",
    'aide_preventif.travaux_warn' => "<b>Seasons:</b> tasks are grouped by season (e.g. \"2026-2027\"), computed automatically but adjustable. At the end of a season, check the unfinished tasks (left column of the table) then <b>\"Carry over the selection\"</b>: they're copied to the chosen season (existing or new), status reset to \"To do\". Nothing carries over automatically — without this action, an unfinished task stays on the old season.",
    'aide_preventif.generation_lede' => "A preventive rule does nothing by itself: it's a generation mechanism that, at regular intervals, turns rules that have come due into actual work orders.",
    'aide_preventif.generation_li1' => "The generated work order automatically carries the <code>[PREVENTIVE]</code> prefix in its description, a <span class=\"pill pill-all\"><span class=\"pill-dot\"></span>To do</span> status, and the <b>\"Preventive\"</b> type (blue badge, different from red for curative).",
    'aide_preventif.generation_li2' => "It then follows <b>exactly the same lifecycle</b> as a standard curative work order: To do → In progress → Done, with the same mandatory closing report (see <a href=\"aide_ot.php\">the \"Create & close a work order\" article</a>).",
    'aide_preventif.generation_li3' => "It stays traceable: from the original rule, the \"History\" button finds every work order it has generated.",
    'aide_preventif.generation_lock' => "On the scheduled day and time, this generation fires automatically via a server-side scheduled task, independently of your clicks in the interface. If a normal due date hasn't turned into a work order and nobody touched it, contact the system administrator rather than looking for why on the Preventive screen.",
    'aide_preventif.generation_tip1' => "The <b>⚡ \"Generate a request\"</b> button (on each rule row, and in its detail sheet) triggers this same generation right away, on demand — without waiting for the normal due date. Useful to recreate an accidentally deleted request, or test a rule that was just created. Like the automatic generation, it creates a <b>request in the validation gateway</b> (see <a href=\"aide_ot.php#portes\">the \"Create & close a work order\" article</a>) — never a work order directly: it still needs normal validation.",
    'aide_preventif.generation_tip2' => "There's no checklist on a preventive work order: the instructions entered at step 4 (description, cause, parts) are simply injected as free text into the work order's description, to be read like any other ticket.",
    'aide_preventif.gestion_lede' => "On each row of the rule list:",
    'aide_preventif.gestion_modifier_h4' => "Edit",
    'aide_preventif.gestion_modifier_p' => "Click the row to open the detail sheet, then \"Edit\" to reopen the pre-filled wizard and change any field.",
    'aide_preventif.gestion_pause_h4' => "Pause (Winter)",
    'aide_preventif.gestion_pause_p' => "Suspends the rule without deleting it: it's greyed out in the list and generates no more work orders until reactivated.",
    'aide_preventif.gestion_supprimer_h4' => "Delete",
    'aide_preventif.gestion_supprimer_p' => "<b>Permanent</b> deletion of the rule, with confirmation. Already-generated work orders stay in the history — only future scheduling stops.",
    'aide_preventif.gestion_historique_h4' => "History",
    'aide_preventif.gestion_historique_p' => "Finds every occurrence already generated for this rule, with its processing status.",
    'aide_preventif.planning_lede' => "A weekly grid: one row per technician, one column per day (Monday to Sunday).",
    'aide_preventif.shot_grille_alt' => "Weekly schedule grid by technician",
    'aide_preventif.shot_grille_cap' => "Each colored card represents a work order the technician has a time entry on that day, with its BI number and planned duration.",
    'aide_preventif.planning_li1' => "The ◀ ▶ arrows (in the bar above the grid) change weeks.",
    'aide_preventif.planning_li2' => "<b>Drag and drop</b> a card to another cell to reassign a technician and/or move the date.",
    'aide_preventif.planning_li3' => "Clicking a card opens the work order's full detail, same as on the Entry & History screen.",
    'aide_preventif.planning_li4' => "Clicking an empty cell (admin) opens the creation of a new work order, with technician and day already pre-filled, type pre-filled as \"Preventive\".",
    'aide_preventif.planning_warn' => "<b>Good to know:</b> dragging and dropping a card currently works for everyone, technician and admin alike — so a technician can reassign a task to a colleague by dragging it, while creating from an empty cell and deleting remain admin-only. Worth knowing to avoid accidental reassignments.",
    'aide_preventif.planning_tip' => "This screen is also where you record your <b>paid leave, RTT, public holidays and sick leave</b>, and track your annualization (1607h target). To understand in detail how each day type is counted — with the legal formula and worked examples — see <a href=\"aide_annualisation.php\">the \"Leave, RTT & Annualization\" article</a>.",
    'aide_preventif.astuces_li1' => "<b>Always assign a technician</b> to a rule if you want it to show up on the Schedule.",
    'aide_preventif.astuces_li2' => "<b>Use \"Pause\"</b> rather than \"Delete\" for seasonal checks (e.g. winterizing) — you keep the history and can reactivate it later.",
    'aide_preventif.astuces_li3' => "<b>Check the filter chips</b> (\"Overdue\", \"Soon\") regularly: it's the fastest way to spot slipping due dates.",
    'aide_preventif.astuces_li4' => "<b>A preventive work order is handled exactly like a curative one</b>: same closing, same mandatory report — no special shortcut to look for.",
    'aide_preventif.astuces_li5' => "<b>Preventive work order deleted by mistake?</b> Find the original rule on the Preventive screen and click ⚡ \"Generate a request\" to recreate it in the validation gateway, without waiting for the next automatic due date.",
    'aide_preventif.gloss1_dt' => "Rule / Preventive plan",
    'aide_preventif.gloss1_dd' => "The definition of a recurring check: what, where, how often, for whom.",
    'aide_preventif.gloss2_dt' => "Scheduling mode",
    'aide_preventif.gloss2_dd' => "Frequency in days (e.g. every 30 days) or fixed weekdays (e.g. every Monday).",
    'aide_preventif.gloss3_dt' => "Due date",
    'aide_preventif.gloss3_dd' => "The date the next check is expected.",
    'aide_preventif.gloss4_dt' => "Time entry",
    'aide_preventif.gloss4_dd' => "A logged time entry for a technician on a work order — it's what makes a card appear on the Schedule.",
    'aide_preventif.devnote_li1' => "Auto-generation (<code>cron_preventif.php</code>) depends on an external scheduled task (system cron) to check server-side if normal due dates aren't turning into work orders. The ⚡ \"Generate a request\" button (action <code>generer_demande</code> in <code>preventif_liste.php</code>) reproduces the same INSERT on demand, outside the cron cycle, never filling in <code>num_bi</code>.",
    'aide_preventif.devnote_li2' => "The \"Auto morning\" checkbox (<code>preventif_regles.auto_matin</code> column) picks, at generation time (cron or manual button), the first technician in alphabetical order on the \"Morning\" shift that day in <code>planning_shifts</code> — empty if nobody or several, with no fallback to the rule's fixed assignee.",
    'aide_preventif.devnote_li3' => "On the Schedule, drag-and-drop (<code>action=update_pointage_planif</code>) isn't restricted to admins server-side — only creating from an empty cell and deleting are, client-side.",

    'aide_ot.page_title_tag' => "Create & Close a Work Order - GMAO Help",
    'aide_ot.hero_tagline' => "The complete guide to the work order, from reported breakdown to closed report.",
    'aide_ot.pill_version' => "Version <b>1.4</b>",
    'aide_ot.pill_updated' => "Updated on <b>09/11/2026</b>",
    'aide_ot.pill_ecrans' => "Screen concerned <b>Entry &amp; History</b>",
    'aide_ot.toc_vue_ensemble' => "Overview",
    'aide_ot.toc_portes' => "The 2 ways to create a work order",
    'aide_ot.toc_formulaire' => "Using the creation wizard",
    'aide_ot.toc_assistant_intelligent' => "The smart guide (duplicates)",
    'aide_ot.toc_cycle' => "The lifecycle of a work order",
    'aide_ot.toc_prise_en_charge' => "Taking charge",
    'aide_ot.toc_cloture' => "Closing a work order",
    'aide_ot.toc_cas_particuliers' => "Special cases",
    'aide_ot.toc_droits' => "Who can do what",
    'aide_ot.toc_astuces' => "Tips & pitfalls",
    'aide_ot.toc_glossaire' => "Glossary",
    'aide_ot.vue_ensemble_lede' => "A <b>BI</b> (work order) — is the record that follows a maintenance job from the very start (a reported breakdown) to the end (the written report). This guide shows you, screen by screen, how to create it, take charge of it, and close it correctly.",
    'aide_ot.journey_creer' => "Create",
    'aide_ot.journey_prendre' => "Take charge",
    'aide_ot.journey_intervenir' => "Work on it",
    'aide_ot.journey_cloturer' => "Close",
    'aide_ot.shot_cartes_alt' => "Per-technician summary cards on the Entry & History screen",
    'aide_ot.shot_cartes_cap' => "At the top of the \"Entry & History\" screen, one card per technician summarizes their workload: urgent, to do, in progress, done, and time already logged.",
    'aide_ot.callout_numero_bi' => "<b>The BI number</b> is generated automatically on creation, in the format <code>BI</code> + year + number, e.g. <code>BI26-014</code>. You never have to make it up: just note it down when you need to mention it to someone (phone, workshop, meeting).",
    'aide_ot.portes_lede' => "A work order can land in your table in two different ways. It's important to be able to tell them apart.",
    'aide_ot.route1_tag' => "Entry & History screen",
    'aide_ot.route1_titre' => "Direct creation",
    'aide_ot.route1_p1' => "You (technician or admin) create the work order yourself by clicking the <b>\"Create a work order\"</b> tile, which opens a guided 4-step wizard. This is the method to use when <b>you</b> spot a breakdown or a task to do.",
    'aide_ot.route1_p2' => "The ticket appears immediately in the table with the status <span class=\"pill pill-afaire\"><span class=\"pill-dot\"></span>To do</span> — ready to be handled.",
    'aide_ot.route2_tag' => "\"Work Request\" portal",
    'aide_ot.route2_titre' => "Request from another department",
    'aide_ot.route2_p1' => "An operator, Production, Quality, or another department submits a request with their name and a personal PIN code (see <a href=\"aide_service.php#demande\">the dedicated article</a>). The ticket arrives with the status <span class=\"pill pill-attente\"><span class=\"pill-dot\"></span>Pending</span>, <b>with no BI number</b>.",
    'aide_ot.route2_p2' => "It shows up in the red \"pending request(s) awaiting validation\" banner. It's up to you to open it and validate it so it becomes a real work order.",
    'aide_ot.shot_bandeau_alt' => "Red alert banner indicating requests awaiting validation",
    'aide_ot.shot_bandeau_cap' => "This banner appears at the top of the screen as soon as an external request is waiting to be turned into a work order.",
    'aide_ot.shot_sas_alt' => "Validation window listing the pending requests",
    'aide_ot.shot_sas_cap' => "The \"validation airlock\": each request shows the description, attached photos and an Urgent badge if flagged as such, then offers Refuse, Messaging, Create the BI (with the technician and date pre-filled) — and for an admin, Send to preventive.",
    'aide_ot.callout_photos' => "A request's record now shows everything the requester provided: <b>attached photos</b> (click to zoom), a clearly visible <b>\"Urgent\"</b> badge if the request was flagged as such, and the number of messages already exchanged, shown right on the <b>Messaging</b> button — enough to judge the situation without opening every tab.",
    'aide_ot.callout_mobile' => "On phone and tablet, the validation airlock first opens on a list of compact <b>badges</b> (request number, requester, equipment, breakdown description, date/time, red dot if urgent) rather than the full record. Tapping a badge shows the full-screen record, with a \"Back to list\" button at the top to go back without losing the other requests.",
    'aide_ot.callout_refuser' => "<b>Refuse</b> deletes nothing: the request gets a real BI number (status <span class=\"pill pill-refuse\"><span class=\"pill-dot\"></span>Refused</span>) and stays visible in the Global History, with the name of the person who refused it and a mandatory reason of at least 20 characters — an actual account (\"plant fully defrosting, no production that day\"), not \"n/a\" or \"ok\". This is what guarantees an audit finds a trace for <b>every</b> preventive task generated, even the ones that didn't lead to a job.",
    'aide_ot.callout_vers_preventif' => "<b>Send to preventive</b> (admin-only): for a one-off request that doesn't need to become a BI right away (e.g. \"lower the panel by 2 metres\"), this button adds it straight to the <b>\"Winter Work\"</b> tab of the \"Winter maintenance\" category on the <a href=\"preventif.php\">Preventive Plan</a> — a checklist of tasks to tick off, with no frequency or automatic BI generation (see <a href=\"aide_preventif.php#travaux-divers\">the details in the Preventive help</a>). The original request is deleted once added to this list. For a genuinely recurring need (rare from a request), create a regular rule instead via \"New rule\" on the Preventive page.",
    'aide_ot.callout_warn_etiquette' => "On the \"Work Request\" portal, you'll sometimes see the label <b>\"Awaiting validation\"</b>. That's a clearer display text for the requester — in the database, the actual status stays <code>En attente</code>, the one you handle via the red banner.",
    'aide_ot.formulaire_lede' => "Clicking the <b>\"Create a work order\"</b> tile opens a 4-step window. Each step can be revisited at any time via the sidebar, and every field has a small help bubble <i class=\"fa-solid fa-circle-question\" style=\"color:var(--accent);\"></i> to click if in doubt.",
    'aide_ot.callout_lock_assistant' => "As long as the window is open, clicking outside it <b>never</b> cancels it — only the <b>\"Cancel\"</b> button or the cross in the top right close the wizard (and lose the current entry). This is deliberate, to avoid losing a half-filled work order to a stray click.",
    'aide_ot.step1_titre' => "Who",
    'aide_ot.step1_desc' => "The requester, and if needed, the external company handling the job.",
    'aide_ot.step2_titre' => "Location",
    'aide_ot.step2_desc' => "The Plant → Area → Line → Zone → Machine cascade.",
    'aide_ot.step3_titre' => "Details",
    'aide_ot.step3_desc' => "Date, type, priority, breakage, fastener check and description.",
    'aide_ot.step4_titre' => "Summary",
    'aide_ot.step4_desc' => "Review of all fields, then click \"Create the work order ticket\".",
    'aide_ot.shot_etape1_alt' => "Wizard step 1: the requester",
    'aide_ot.shot_etape1_cap' => "Step 1 — Who is reporting the job.",
    'aide_ot.shot_etape2_alt' => "Wizard step 2: the location",
    'aide_ot.shot_etape2_cap' => "Step 2 — The location cascade.",
    'aide_ot.shot_etape3_alt' => "Wizard step 3: the job details",
    'aide_ot.shot_etape3_cap' => "Step 3 — Type, priority and description.",
    'aide_ot.shot_etape4_alt' => "Wizard step 4: the summary",
    'aide_ot.shot_etape4_cap' => "Step 4 — The summary before submitting.",
    'aide_ot.tbl_th_champ' => "Field",
    'aide_ot.tbl_th_etape' => "Step",
    'aide_ot.tbl_th_description' => "Description",
    'aide_ot.tbl_th_obligatoire' => "Required?",
    'aide_ot.req_auto' => "Auto",
    'aide_ot.req_si_besoin' => "If needed",
    'aide_ot.req_conseille' => "Recommended*",
    'aide_ot.row1_champ' => "Requester",
    'aide_ot.row1_desc' => "Your name. Pre-filled and locked for a technician; an admin can choose anyone.",
    'aide_ot.row2_champ' => "Planned technician",
    'aide_ot.row2_desc' => "Admin-only: pre-assign someone right at creation.",
    'aide_ot.row3_champ' => "External company",
    'aide_ot.row3_desc' => "Tick \"subcontracted job\" then choose the company if the task is given to an outside contractor.",
    'aide_ot.row4_champ' => "Plant → Area → Line → Zone → Machine",
    'aide_ot.row4_desc' => "Cascading location: each dropdown unlocks once the previous one is filled. If the machine doesn't exist in the database yet, the field becomes free text.",
    'aide_ot.row5_champ' => "Date",
    'aide_ot.row5_desc' => "Date of the job, today by default.",
    'aide_ot.row6_champ' => "Type",
    'aide_ot.row6_desc' => "Curative / Preventive / Project.",
    'aide_ot.row7_champ' => "Priority",
    'aide_ot.row7_desc' => "Normal or Urgent — Urgent makes the ticket blink in the table.",
    'aide_ot.row8_champ' => "Breakage",
    'aide_ot.row8_desc' => "Tick if the job involves broken equipment.",
    'aide_ot.row9_champ' => "Fastener check",
    'aide_ot.row9_desc' => "Tick if the job includes a fastener/tightening check.",
    'aide_ot.row10_champ' => "Description",
    'aide_ot.row10_desc' => "The text explaining the breakdown or the task to do.",
    'aide_ot.callout_warn_champs' => "<b>* No field is technically enforced</b> — the wizard lets you move step by step even leaving the machine or description empty. Just because you can doesn't mean you should: a work order with no machine or description is unreadable for the colleague who picks it up. Always fill in at least <b>Machine</b>, <b>Type</b> and <b>Description</b>.",
    'aide_ot.callout_tip_bulle' => "Not sure about a field? Click its <i class=\"fa-solid fa-circle-question\"></i> icon — an illustrated help bubble opens with concrete examples, without leaving the wizard.",
    'aide_ot.assistant_intelligent_lede' => "While you fill in the wizard, two contextual panels appear automatically to help you avoid recreating a work order that already exists on the same machine.",
    'aide_ot.step_historique_titre' => "Step 2 — Machine history",
    'aide_ot.step_historique_desc' => "As soon as a machine is selected, a blue panel lists every work order already logged on it (how many total, how many still open), with each one's status and date. The list scrolls if it's long.",
    'aide_ot.step_similaires_titre' => "Step 3 — Similar work orders",
    'aide_ot.step_similaires_desc' => "While typing the description, an orange panel appears if one or more existing work orders have a similar description (keyword overlap, same machine given priority) — up to 3 suggestions, closest match first.",
    'aide_ot.callout_tip_clic_suggestion' => "Clicking a suggested work order asks for confirmation, then <b>closes the current wizard</b> and opens the existing one: the editing wizard if it's still active, or directly <b>the report/close window</b> if it's already done — to see what's already been done before deciding whether to continue on it rather than create a new one.",
    'aide_ot.callout_warn_aide_pas_ia' => "This is <b>a helper, not an AI</b>: matching is done purely by shared keywords in the description, with nothing sent to an external service. Nothing is ever blocking — these panels don't prevent you from creating a new work order, they just help you spot a duplicate before submitting.",
    'aide_ot.cycle_lede' => "A work order goes through a series of statuses, shown as colored badges in the table. Here's the full path, and who triggers each step.",
    'aide_ot.pill_en_attente' => "Pending",
    'aide_ot.pill_a_faire' => "To do",
    'aide_ot.pill_en_cours' => "In progress",
    'aide_ot.pill_terminee' => "Done",
    'aide_ot.pill_urgent' => "Urgent",
    'aide_ot.pill_refusee' => "Refused",
    'aide_ot.cy_attente_trig' => "Request created by another department",
    'aide_ot.cy_attente_who' => "Via the portal",
    'aide_ot.cy_afaire_trig' => "Validated in the red banner → BI number assigned",
    'aide_ot.cy_afaire_who' => "Maintenance",
    'aide_ot.cy_cours_trig' => "Click on the status badge in the table",
    'aide_ot.cy_cours_who' => "Technician",
    'aide_ot.cy_termine_trig' => "Another click + work report filled in",
    'aide_ot.cy_termine_who' => "Technician",
    'aide_ot.shot_tableau_alt' => "Work order table with colored status badges",
    'aide_ot.shot_tableau_cap' => "The work order table: every status badge is clickable to move the work order to the next step. Notice the \"Entry locked\" padlock once the ticket is done.",
    'aide_ot.callout_lock_reouverture' => "<b>Reopening:</b> a \"Done\" work order can be put back to \"To do\" with a simple click on its status badge, after confirmation — but only by an <b>administrator</b>. If you're a technician and need to reopen a record closed by mistake, ask an admin. This rule also applies when you open an already-closed work order from the wizard's <a href=\"#assistant-intelligent\">smart guide</a>: a technician sees the report there in <b>read-only</b> mode (report and \"+ TIME\" / \"Save, leave open\" buttons disabled), only an admin can edit or reopen it from that window.",
    'aide_ot.callout_tip_urgent' => "<b>\"Urgent\" isn't a separate status</b>: it's a priority set at creation, which makes the <span class=\"pill pill-urgent pulse-badge\"><span class=\"pill-dot\"></span>Urgent</span> badge blink red as long as the ticket is \"To do\". Once taken in hand, it becomes a regular \"In progress\" badge.",
    'aide_ot.prise_en_charge_lede' => "Nothing simpler: in the work order table, find the status badge on the relevant row.",
    'aide_ot.pec_step1_titre' => "Find a \"To do\" ticket",
    'aide_ot.pec_step1_desc' => "Use the counters at the top of the table (Urgent / To do / In progress / Done) to filter quickly, or browse the list.",
    'aide_ot.pec_step2_titre' => "Click directly on the status badge",
    'aide_ot.pec_step2_desc' => "A single click on the badge moves the ticket to \"In progress\". No confirmation window.",
    'aide_ot.pec_step3_titre' => "A 0h time entry is created for you automatically",
    'aide_ot.pec_step3_desc' => "If no time was logged yet on this ticket, the app creates a time entry under your name (0h, ticket date). This entry is what makes you show up as a technician on the record — remember to then update your actual time via the <b>\"+ TIME\"</b> button.",
    'aide_ot.callout_warn_pec' => "Moving a ticket to \"In progress\" <b>doesn't formally assign it</b> to you — the original \"requester\" field doesn't change, and no take-charge time is stamped. Your time entry is what counts if several people work on the same work order.",
    'aide_ot.cloture_lede' => "This is the most important step: it's where your work becomes an actual, usable maintenance history.",
    'aide_ot.clo_step1_titre' => "Click the status badge again",
    'aide_ot.clo_step1_desc' => "On an \"In progress\" ticket, this second click opens the closing window instead of changing the status directly.",
    'aide_ot.clo_step2_titre' => "Check the summary shown",
    'aide_ot.clo_step2_desc' => "BI number, location/machine, total time logged so far, requester, technician(s) and breakdown description are shown read-only at the top of the window.",
    'aide_ot.clo_step3_titre' => "Write the \"Technical Work Report\"",
    'aide_ot.clo_step3_desc' => "This is <b>the only mandatory field in the entire work order journey.</b> Describe the corrective actions taken: diagnosis, parts replaced, adjustments, tests carried out. Be concrete — this is the text a colleague will read in case of a recurring breakdown.",
    'aide_ot.clo_step4_titre' => "Click \"Confirm Closing\"",
    'aide_ot.clo_step4_desc' => "The status moves to \"Done\", a confirmation message appears, and time entry locks in the table (badge <b>\"🔒 Entry locked\"</b> in place of the \"+ TIME\" button).",
    'aide_ot.shot_modale_alt' => "Work order closing window with the mandatory report field",
    'aide_ot.shot_modale_cap' => "The closing window: location, cumulative time, requester and technicians are recalled read-only above the \"Technical Work Report\" field.",
    'aide_ot.callout_warn_rapport_vide' => "If you leave the report empty, the app refuses to close with the message <b>\"Please enter a technical report before closing\"</b>. That's expected: without this text, the work order would have no historical value.",
    'aide_ot.callout_tip_enregistrer_ouvert' => "<b>Not finished? A \"Save, leave open\" button</b> is available right next to \"Confirm Closing\". It saves the report written so far and puts the work order back to \"In progress\", without requiring a finished text — useful for noting where you're at without forcing a premature closing. A <b>\"+ TIME\"</b> button is also right there in this window to add a time entry without closing it.",
    'aide_ot.callout_tip_carnet' => "<b>The logbook:</b> as long as the work order isn't done, the detailed record offers an <b>\"interim note\"</b> area (e.g. \"part ordered this morning, awaiting delivery\"). Use it to leave progress notes as you go — once the work order is closed, these notes become a read-only history, separate from the final report.",
    'aide_ot.callout_tip_demandeur_voit' => "<b>The requester sees more detail once the BI is done:</b> for a ticket created from the \"Work Request\" portal, the department behind the request finds, in their own tracking, the cumulative <b>work hours</b> (total time logged), the <b>completion date</b> (date of the last time entry), and any <b>photo</b> attached to the BI — keep this in mind, this information doesn't stay confined to your internal tools.",
    'aide_ot.callout_lock_pdf' => "From the detailed record, the <b>\"EXPORT AS PDF\"</b> button generates, at any time, a printable report named <code>RI_&lt;BI number&gt;.pdf</code>.",
    'aide_ot.cas_particuliers_lede' => "A few situations that fall outside the standard path.",
    'aide_ot.case_soustraitance_titre' => "Subcontracted job",
    'aide_ot.case_soustraitance_desc' => "Tick \"subcontracted job\" at creation and choose the external company. The record then shows \"Subcontractor: …\" and a <b>\"GENERATE PDP\"</b> button (prevention plan) appears.",
    'aide_ot.case_urgent_titre' => "Urgent priority",
    'aide_ot.case_urgent_desc' => "A \"To do\" ticket marked Urgent shows a blinking red bell in the table. Handle it first — the blinking stops as soon as it moves to \"In progress\".",
    'aide_ot.case_messagerie_titre' => "Messaging on a ticket",
    'aide_ot.case_messagerie_desc' => "For tickets coming from an external request, a \"MESSAGING\" button lets you exchange with the requester directly on the ticket. Unread messages show a red dot and a dedicated filter in the table.",
    'aide_ot.case_suppression_titre' => "Deleting a work order",
    'aide_ot.case_suppression_desc' => "Possible individually (trash icon) or in bulk (multi-select). <b>Admin-only</b> — a technician who tries sees a refusal message.",
    'aide_ot.case_impression_titre' => "Printing a card for the board",
    'aide_ot.case_impression_desc' => "The printer icon on a work order generates a compact card — machine, location, description, assigned technician(s), logbook — to pin up on the workshop board. To print several at once, check the work orders then click <b>\"Print selection\"</b>: every card prints at the same size, 2 per line. <b>Multi-select is admin-only</b>, same as for deletion.",
    'aide_ot.droits_lede' => "The screen adapts to your role. Here's the summary.",
    'aide_ot.tbl_th_action' => "Action",
    'aide_ot.tbl_th_technicien' => "Technician",
    'aide_ot.tbl_th_admin' => "Admin",
    'aide_ot.droit1_action' => "Create a work order",
    'aide_ot.droit2_action' => "Freely choose the requester",
    'aide_ot.droit2_tech' => "Locked to self",
    'aide_ot.droit3_action' => "Pre-assign a technician at creation",
    'aide_ot.droit4_action' => "Take charge of / close a work order",
    'aide_ot.droit5_action' => "Edit a colleague's time entry",
    'aide_ot.droit5_tech' => "Own time entries only",
    'aide_ot.droit6_action' => "Delete a work order",
    'aide_ot.droit7_action' => "Reopen a closed work order",
    'aide_ot.droit8_action' => "Add time / edit the report of an already-closed work order",
    'aide_ot.droit8_tech' => "Read-only",
    'aide_ot.droit9_action' => "Access to Preventive, KPI, Stats, Machines, Users",
    'aide_ot.droit9_tech' => "Menus hidden",
    'aide_ot.astuces_li1' => "<b>Always fill in the description</b>, even briefly — it's the field your colleagues, and you yourself, will read most three months later.",
    'aide_ot.astuces_li2' => "<b>Log your time as you go</b> rather than at the last moment: once the work order is closed, time entry locks.",
    'aide_ot.astuces_li3' => "<b>Don't leave a work order \"In progress\" indefinitely</b> — use the logbook (interim note) to say where you're at if the job spans several days.",
    'aide_ot.astuces_li4' => "<b>A work order with no machine selected</b> is still usable but complicates per-equipment statistics — always prefer the Plant → Area → Line → Zone → Machine cascade.",
    'aide_ot.astuces_li5' => "<b>An unhandled external request</b> stays invisible to the requester until it has a BI number: remember to check the red validation banner regularly.",
    'aide_ot.astuces_li6' => "<b>Before submitting a new work order</b>, check the panels of the <a href=\"#assistant-intelligent\">smart guide</a> (steps 2 and 3): if a very similar work order already exists and isn't finished, it may be better to continue on it rather than open a duplicate.",
    'aide_ot.gloss1_dt' => "BI",
    'aide_ot.gloss1_dd' => "Work order — the generic name for any maintenance job tracked in the CMMS, once it has a number (e.g. BI26-014).",
    'aide_ot.gloss2_dt' => "Requester",
    'aide_ot.gloss2_dd' => "The person who created the ticket or reported the breakdown.",
    'aide_ot.gloss3_dt' => "Time entry",
    'aide_ot.gloss3_dd' => "A logged line of time spent, tied to a technician and a ticket.",
    'aide_ot.gloss4_dt' => "Validation airlock",
    'aide_ot.gloss4_dd' => "The red banner listing external \"Pending\" requests to turn into BIs.",
    'aide_ot.gloss5_dt' => "PDP",
    'aide_ot.gloss5_dd' => "Prevention Plan — a document generated for a job given to an outside company.",
    'aide_ot.gloss6_dt' => "Logbook",
    'aide_ot.gloss6_dd' => "The interim note of an ongoing BI, visible as long as it isn't closed.",
    'aide_ot.gloss7_dt' => "Work report",
    'aide_ot.gloss7_dd' => "The final account, the only mandatory field to close a BI.",
    'aide_ot.devnote_intro' => "Points noticed while reading the code, worth keeping in mind on the admin side:",
    'aide_ot.devnote_li1' => "No field in the creation wizard is enforced on the app side (no <code>required</code> attribute, moving between steps imposes no validation) — entry discipline relies entirely on the team.",
    'aide_ot.devnote_li2' => "Permission checks (deletion, reopening, editing others' time entries) are done <b>client-side only</b>: <code>api.php</code> doesn't recheck the role for these actions. The read-only lock on the closing window for an already-done work order (new with the smart guide) follows the same logic — it's an interface protection, not a server one.",
    'aide_ot.devnote_li3' => "The \"Awaiting validation\" label shown on the requester portal maps in the database to the status <code>En attente</code> — no separate value stored.",
    'aide_ot.devnote_li4' => "The wizard's duplicate detection (<code>#assistant-intelligent</code>) runs entirely client-side on already-loaded data (<code>tasks</code>): keyword overlap (Jaccard score, 0.25 threshold), no network call or external service.",

    'aide_planning.page_title_tag' => "Understand & Fill in the Schedule - GMAO Help",
    'aide_planning.hero_tagline' => "The weekly grid, the checkboxes, and how they move your hours balance.",
    'aide_planning.pill_version' => "Version <b>1.0</b>",
    'aide_planning.pill_updated' => "Updated on <b>08/20/2026</b>",
    'aide_planning.pill_ecrans' => "Screen concerned <b>Schedule</b>",
    'aide_planning.toc_vue_ensemble' => "Overview",
    'aide_planning.toc_naviguer' => "Navigating between weeks",
    'aide_planning.toc_remplir_case' => "Filling in a cell",
    'aide_planning.toc_cases_evenements' => "Every cell, in detail",
    'aide_planning.toc_avance_retard' => "The hours balance explained",
    'aide_planning.toc_exemple' => "Worked example, week by week",
    'aide_planning.toc_remplissage_rapide' => "Filling in several days at once",
    'aide_planning.toc_bons_intervention' => "Work orders on the schedule",
    'aide_planning.toc_planning_annuel' => "The Annual Schedule",
    'aide_planning.toc_droits' => "Who can do what",
    'aide_planning.toc_astuces' => "Tips & pitfalls",
    'aide_planning.toc_glossaire' => "Glossary",
    'aide_planning.vue_ensemble_lede' => "The <b>Schedule</b> is a grid: one row per technician, one column per day of the week. Each cell can hold a <b>worked shift</b> (morning, afternoon, night...), an <b>event</b> (leave, RTT, sick leave...), an <b>on-call</b> flag, and the number of <b>hours worked</b>. This same data is what automatically feeds your annualized hours counter and the \"ahead / behind\" indicator you see on your record.",
    'aide_planning.shot_grille_alt' => "Weekly schedule grid with one row per technician",
    'aide_planning.shot_grille_cap' => "The weekly grid: on the left, each technician with their weekly hours total and their annualized total; in the middle, one cell per day.",
    'aide_planning.vue_ensemble_p2' => "In each cell, you can see up to three things:",
    'aide_planning.vue_li1' => "<b>A shift/event badge</b> — color + label (e.g. \"Morning · 7h\", \"Paid leave\", \"RTT\").",
    'aide_planning.vue_li2' => "<b>One or more work orders (BI)</b> — small numbered tags, if the technician logged time on a job that day.",
    'aide_planning.vue_li3' => "<b>A note icon</b> <i class=\"fa-solid fa-note-sticky\" style=\"color:var(--gelpam-orange);\"></i> — if a remark was left (e.g. \"arrived at 9am, left at 3:30pm\").",
    'aide_planning.callout_annuel' => "Clicking a technician's name, avatar or total (the block on the left) opens their <a href=\"#planning-annuel\"><b>Annual Schedule</b></a> directly — the full calendar for the year, not just the week shown.",
    'aide_planning.naviguer_lede' => "Three ways to change week, all equivalent:",
    'aide_planning.case_fleches_titre' => "The arrows on the edges",
    'aide_planning.case_fleches_desc' => "Two semi-transparent arrows sit on the left and right edges of the screen. A click moves one week back or forward.",
    'aide_planning.case_glisser_titre' => "Dragging a work order towards the edge",
    'aide_planning.case_glisser_desc' => "While dragging a BI, bring it near the left or right edge of the screen: the week scrolls automatically (with a \"Week XX\" marker on screen) so you can drop the BI on another week without releasing the mouse.",
    'aide_planning.case_repere_titre' => "The \"Week XX\" marker",
    'aide_planning.case_repere_desc' => "At the top of the screen, the week number and exact dates (\"from ... to ...\") shown always confirm the period you're viewing.",
    'aide_planning.remplir_case_lede' => "Click anywhere in an empty cell (or on its existing badge) to open the scheduling window. It's the central screen of this whole guide.",
    'aide_planning.shot_modal_alt' => "Cell scheduling window: Shift, Event, On-call, Hours, Note",
    'aide_planning.shot_modal_cap' => "The window that opens when you click a cell: three groups of clickable \"chips\" (Shift, Event, On-call), then hours worked and a free-text note.",
    'aide_planning.rc_step1_titre' => "Choose a Shift (if the technician worked)",
    'aide_planning.rc_step1_desc' => "Morning, Afternoon, Night or Full day — only one chip can be active at a time. Clicking an already-active chip deselects it.",
    'aide_planning.rc_step2_titre' => "Or choose an Event (if the technician is absent)",
    'aide_planning.rc_step2_desc' => "Paid leave, RTT, Sick leave, Rest day — only one active at a time, and it automatically clears the chosen Shift (you can't be \"on leave\" and \"at work\" the same day). Half-day leave and Public holiday work differently: see the next section.",
    'aide_planning.rc_step3_titre' => "Add an On-call flag if needed",
    'aide_planning.rc_step3_desc' => "Standard on-call or Cold on-call — purely informational, it has no effect on hours due or the hours balance, only the badge shows on the schedule.",
    'aide_planning.rc_step4_titre' => "Enter the hours worked",
    'aide_planning.rc_step4_desc' => "With the <b>−</b> / <b>+</b> buttons (0.5h steps) or by typing the number directly. This figure is what feeds into the real weekly and yearly total.",
    'aide_planning.rc_step5_titre' => "Add a note if needed",
    'aide_planning.rc_step5_desc' => "A delay, an early departure, a specific event... This note is only visible to the technician concerned and to administrators — never to other colleagues.",
    'aide_planning.rc_step6_titre' => "Save",
    'aide_planning.rc_step6_desc' => "The <b>\"Save\"</b> button confirms the cell. The <b>\"Clear\"</b> button empties the cell entirely (shift, event, on-call, hours and note).",
    'aide_planning.callout_objectif_direct' => "While you fill in the window, the <b>\"Annualized target\"</b> bar at the bottom right updates <b>live</b> — you see the effect of your entry on your hours counter immediately, even before saving.",
    'aide_planning.cases_evenements_lede' => "Not all cells are equal: some are mutually exclusive, others stack. Here's the full detail, shift by shift and event by event.",
    'aide_planning.tbl2_th_case' => "Cell",
    'aide_planning.tbl2_th_groupe' => "Group",
    'aide_planning.tbl2_th_heures_dues' => "Hours \"due\" that day",
    'aide_planning.tbl2_th_cumule' => "Stacks with",
    'aide_planning.row1_case' => "Morning / Afternoon / Night / Full day",
    'aide_planning.row1_groupe' => "Shift",
    'aide_planning.row1_heures' => "7h (normal day)",
    'aide_planning.row1_cumule' => "Half-day leave, Public holiday",
    'aide_planning.row2_case' => "Half-day leave (½ paid leave)",
    'aide_planning.row2_groupe' => "Event to tick",
    'aide_planning.row2_heures' => "3.5h instead of 7h",
    'aide_planning.row2_cumule' => "A worked shift only",
    'aide_planning.row3_case' => "Paid leave",
    'aide_planning.row3_groupe' => "Event",
    'aide_planning.row3_heures' => "0h",
    'aide_planning.row3_cumule' => "Nothing (exclusive)",
    'aide_planning.row4_case' => "Public holiday",
    'aide_planning.row4_groupe' => "Event to tick",
    'aide_planning.row4_heures' => "0h if not worked · 7h normally if worked",
    'aide_planning.row4_cumule' => "A worked shift",
    'aide_planning.row5_case' => "RTT",
    'aide_planning.row5_groupe' => "Event",
    'aide_planning.row5_heures' => "7h (but 0h done)",
    'aide_planning.row5_cumule' => "Nothing (exclusive)",
    'aide_planning.row6_case' => "Sick leave",
    'aide_planning.row6_groupe' => "Event",
    'aide_planning.row6_heures' => "7h, credited automatically",
    'aide_planning.row6_cumule' => "Nothing (exclusive)",
    'aide_planning.row7_case' => "Rest day",
    'aide_planning.row7_groupe' => "Event",
    'aide_planning.row7_heures' => "0h",
    'aide_planning.row7_cumule' => "Nothing (exclusive)",
    'aide_planning.row8_case' => "Empty cell (weekday)",
    'aide_planning.row8_heures' => "7h anyway",
    'aide_planning.row9_case' => "Empty cell (Saturday/Sunday)",
    'aide_planning.row9_heures' => "0h",
    'aide_planning.card_poste_titre' => "Shift (Morning / Afternoon / Night / Full day)",
    'aide_planning.card_poste_desc' => "The actual work pattern for that day. Counted as a normal day: <b>7h due</b>, compared against the hours you enter just below.",
    'aide_planning.card_cp_titre' => "Paid leave",
    'aide_planning.card_cp_desc' => "0h due: a paid leave day is never counted as \"to catch up\". It uses up one day of the annual quota — <b>25 days</b> on weekdays, <b>5</b> extra days reserved for Saturdays (30 total, two separate counters). Taken on a Sunday, it uses up nothing since Sunday is never worked anyway.",
    'aide_planning.card_demiconge_titre' => "Half-day leave (½ paid leave)",
    'aide_planning.card_demiconge_desc' => "A <b>separate</b> checkbox, not a shift: it reduces the hours due to 3.5h instead of 7h. It can only be ticked alongside an actual worked shift (morning, afternoon...) — ticking a full-day event (paid leave, RTT, sick leave, rest day) automatically unticks it, and vice versa.",
    'aide_planning.card_ferie_titre' => "Public holiday",
    'aide_planning.card_ferie_desc' => "Ticked like half-day leave, alongside a shift. <b>Not worked</b>: 0h due. <b>Worked</b> (a shift is also ticked): counted as a normal day, 7h due — working a public holiday doesn't create a hidden bonus in this counter (the pay premium is a separate payroll matter). Recognized French public holidays are <b>auto-ticked</b> as long as nobody has entered anything for you that day.",
    'aide_planning.card_rtt_titre' => "RTT",
    'aide_planning.card_rtt_desc' => "Watch out, classic pitfall: unlike paid leave, an RTT day still counts as <b>7h due</b>, with 0h done. In practice, taking an RTT day <b>debits 7h from your lead</b> — that's expected, an RTT day \"spends\" hours you've already banked by working more than 35h some weeks.",
    'aide_planning.card_maladie_titre' => "Sick leave",
    'aide_planning.card_maladie_desc' => "7h due, but the app <b>credits it automatically</b> as if it had been worked (even if you enter no hours). Result: sick leave is completely <b>neutral</b> for your counter — it doesn't penalize you, but doesn't move you forward either.",
    'aide_planning.card_repos_titre' => "Rest day",
    'aide_planning.card_repos_desc' => "The legal weekly rest day, on a rotation that can fall on any day of the week (not necessarily Saturday/Sunday). 0h due: this day was never \"to be worked\", so taking it costs nothing.",
    'aide_planning.card_astreinte_titre' => "On-call (standard / cold)",
    'aide_planning.card_astreinte_desc' => "Purely informational: affects <b>neither</b> hours due, <b>nor</b> hours done, <b>nor</b> the hours balance. Just a visual badge on the schedule to know who's on call.",
    'aide_planning.callout_warn_case_vide' => "<b>The number one cause of \"false lag\": a weekday cell left completely empty.</b> Even if the technician actually worked, the app can only count what's entered. A weekday with no cell ticked stays due at 7h by default (unless it's an automatically recognized public holiday) — with nothing entered against it, that shows up as <b>-7h</b> on the balance counter, as if the technician did nothing.",
    'aide_planning.avance_retard_lede' => "You've probably already seen the phrase <b>\"+12h ahead of 35h/week\"</b> or <b>\"8h behind on 35h/week\"</b> under a progress bar. Here's how that figure is calculated, without jargon.",
    'aide_planning.journey2_dues' => "Hours due",
    'aide_planning.journey2_faites' => "Hours done",
    'aide_planning.journey2_ecart' => "Gap (ahead or behind)",
    'aide_planning.ar_p1' => "<b>\"Due\" hours</b> are what you should have accumulated as of today if you worked exactly 35h a week (i.e. 7h per working day) since the start of the period — April 1st. Every weekday counts as 7h \"due\", except those covered by the table in the previous section (paid leave = 0h, rest day = 0h, unworked public holiday = 0h, half-day leave = 3.5h). Weekends owe nothing by default, unless actually worked.",
    'aide_planning.ar_p2' => "<b>\"Done\" hours</b> are the sum of all the hours you've entered in your cells, plus the \"as if\" 7h automatically credited for each sick day.",
    'aide_planning.ar_p3' => "<b>The gap</b> = hours done − hours due. Positive, you're <span class=\"chip-key\"><span class=\"chip-dot\" style=\"background:var(--success);\"></span>ahead</span>. Negative, you're <span class=\"chip-key\"><span class=\"chip-dot\" style=\"background:var(--danger);\"></span>behind</span>.",
    'aide_planning.shot_ecart_alt' => "\"Understand my hours balance\" window with the month-by-month detail",
    'aide_planning.shot_ecart_cap' => "The \"i\" help bubble next to the 35h/week marker opens this detail: hours due, hours done, total gap, month-by-month gap, and above all the list of weekdays left with no entry at all.",
    'aide_planning.callout_tip_jours_sans_saisie' => "This help bubble explicitly lists <b>weekdays with no entry at all</b> (no shift, no paid leave, no RTT, no holiday). This is almost always the real explanation for a lag that seems unjustified: fill in these days (worked shift or leave taken) and the counter climbs back up immediately.",
    'aide_planning.ar_p4' => "Two further adjustments reduce the number of hours due over the whole year (so they raise the lead):",
    'aide_planning.card_fractionnement_titre' => "Split leave (Art. 6)",
    'aide_planning.card_fractionnement_desc' => "Days granted case by case by HR depending on the conditions under which the main leave was taken — <b>1 day = -7h</b>, <b>2 days = -14h</b> off the annual target. Set from the <a href=\"#planning-annuel\">Annual Schedule</a>, \"Split leave\" dropdown.",
    'aide_planning.card_semaine48_titre' => "48h weeks (Art. 3)",
    'aide_planning.card_semaine48_desc' => "Any week where total hours entered reaches 48h or more grants <b>-4h</b> off the annual target — detected automatically, no specific entry needed.",
    'aide_planning.exemple_lede' => "A fictional example to clearly see the concrete effect of each cell. Imagine a technician's week filled in like this:",
    'aide_planning.tbl3_th_jour' => "Day",
    'aide_planning.tbl3_th_case' => "Cell ticked",
    'aide_planning.tbl3_th_heures_dues' => "Hours due",
    'aide_planning.tbl3_th_heures_faites' => "Hours done",
    'aide_planning.tbl3_th_ecart' => "Day's gap",
    'aide_planning.ex_lundi' => "Monday",
    'aide_planning.ex_lundi_case' => "Morning, 7h entered",
    'aide_planning.ex_mardi' => "Tuesday",
    'aide_planning.ex_mardi_case' => "<i>Nothing entered, forgotten</i>",
    'aide_planning.ex_mercredi' => "Wednesday",
    'aide_planning.ex_mercredi_case' => "RTT",
    'aide_planning.ex_jeudi' => "Thursday",
    'aide_planning.ex_jeudi_case' => "Paid leave",
    'aide_planning.ex_vendredi' => "Friday",
    'aide_planning.ex_vendredi_case' => "Morning + worked public holiday, 7h entered",
    'aide_planning.ex_samedi' => "Saturday",
    'aide_planning.ex_dimanche' => "Sunday",
    'aide_planning.ex_rien_non_travaille' => "<i>Nothing (not worked)</i>",
    'aide_planning.ex_total_label' => "Week total",
    'aide_planning.exemple_conclusion' => "Result: <b>-7h for the week</b>, despite two days actually worked at 7h and a correctly taken paid leave day. The cause is <b>not</b> the paid leave (0h due, neutral): it's the combination of <b>the forgotten Tuesday</b> (-7h, a pure entry gap) and <b>Wednesday's RTT</b>, which normally debits 7h from the lead already banked. Simply filling in Tuesday would bring the week's gap straight back to 0h.",
    'aide_planning.remplissage_rapide_lede' => "To set a week of paid leave or a series of identical shifts without opening each day one by one, use the <b>\"Fill in several days\"</b> button at the bottom of the scheduling window.",
    'aide_planning.shot_bulk_alt' => "Bulk-fill window over a date range",
    'aide_planning.shot_bulk_cap' => "Choose a date range, optionally tick \"Exclude weekends\", set up the same cell (Shift/Event/On-call/Hours) as for a single entry, then \"Apply\".",
    'aide_planning.rr_step1_titre' => "Choose the period",
    'aide_planning.rr_step1_desc' => "A start date and an end date. The \"Exclude weekends\" box is ticked by default — untick it if you also need to cover Saturdays/Sundays.",
    'aide_planning.rr_step2_titre' => "Set up the cell to apply",
    'aide_planning.rr_step2_desc' => "Exactly the same Shift / Event / On-call chips and the same Hours field as for an individual cell, with the same stacking rules.",
    'aide_planning.rr_step3_titre' => "Check the preview, then Apply",
    'aide_planning.rr_step3_desc' => "A preview summarizes what's about to be written before you confirm.",
    'aide_planning.callout_warn_ecrase' => "Bulk-fill <b>overwrites</b> anything already on the days concerned (shift, event, on-call, hours) — double-check the period before clicking \"Apply\".",
    'aide_planning.bons_intervention_lede' => "The schedule also shows, next to the day's shift, a small tag for each work order (BI) the technician logged time on that day (see <a href=\"aide_ot.php\">the work order guide</a> for creation and time entries).",
    'aide_planning.bi_li1' => "<b>Clicking a BI tag</b> opens its detailed record directly.",
    'aide_planning.bi_li2' => "<b>Dragging a tag</b> to another cell moves the BI (and its time entry) to another day or another technician — admin-only. A technician sees their own BIs but can't drag them onto a colleague.",
    'aide_planning.bi_li3' => "In the scheduling window itself, the <b>\"Work orders for the day\"</b> section lists at the top every BI the technician has on that specific date, with a colored status and a click to open the detail.",
    'aide_planning.planning_annuel_lede' => "Accessible by clicking a technician's name in the grid, or the <b>\"View full annual schedule\"</b> button in the scheduling window. It's the full calendar for the current period (from April 1st to the following March 31st), month by month.",
    'aide_planning.shot_annuel_alt' => "Annual Schedule: full calendar with quota summary",
    'aide_planning.shot_annuel_cap' => "At the top: the annual target progress bar and the 35h/week marker. Below: the quota summary (paid leave, Saturday leave, RTT, sick leave, shifts, on-call). Further down: the month-by-month calendar.",
    'aide_planning.card_objectif_titre' => "Annual target",
    'aide_planning.card_objectif_desc' => "1607h by default (the French legal threshold), but customizable per technician. <b>Anyone can change their own target</b> (or an admin, anyone's), via the small number field and the <i class=\"fa-solid fa-check\"></i> button.",
    'aide_planning.card_fractionnement2_titre' => "Split leave",
    'aide_planning.card_fractionnement2_desc' => "Dropdown 0d / 1d (-7h) / 2d (-14h) — same permissions as the target: the technician concerned or an admin.",
    'aide_planning.card_recap_titre' => "Quota summary",
    'aide_planning.card_recap_desc' => "One tile per category: paid leave (25d), Saturday leave (5d), RTT and sick leave (no fixed quota, just a counter), and shifts/on-call already scheduled for the year.",
    'aide_planning.card_alerte_cp_titre' => "Summer paid-leave alert",
    'aide_planning.card_alerte_cp_desc' => "If more than <b>12 consecutive working days of paid leave</b> overlap the period from July 15 to September 30, an alert badge appears on the paid leave tile (contractual cap, Art. 6 of the annualization agreement).",
    'aide_planning.pa_p_calendrier' => "On the calendar itself, each day shows a mini shift/event badge and, for past days, a small green (ahead) or red (behind) badge showing that specific day's gap. Each month totals its hours and its own gap.",
    'aide_planning.callout_tip_bulle_ecart' => "The <i class=\"fa-solid fa-circle-info\"></i> button next to the 35h/week marker opens the <b>\"Understand my hours balance\"</b> bubble detailed in the <a href=\"#avance-retard\">previous section</a>.",
    'aide_planning.callout_lock_annualisation' => "For the full legal 1607h formula (detailed calculation, leave, public holidays) and the annualization agreement's rules, see the dedicated article <a href=\"aide_annualisation.php\">Leave, RTT &amp; Annualization</a>.",
    'aide_planning.droits_lede' => "The schedule adapts to your role. Here's the summary.",
    'aide_planning.tbl4_th_action' => "Action",
    'aide_planning.tbl4_th_technicien' => "Technician",
    'aide_planning.tbl4_th_admin' => "Admin",
    'aide_planning.droit1_action' => "View the weekly grid",
    'aide_planning.txt_toute_equipe' => "The whole team",
    'aide_planning.droit2_action' => "Fill in / edit a cell",
    'aide_planning.txt_ses_cases' => "Own cells only",
    'aide_planning.txt_nimporte_qui' => "Anyone",
    'aide_planning.droit3_action' => "View the annual schedule",
    'aide_planning.txt_le_sien' => "Own only",
    'aide_planning.droit4_action' => "Edit the annual target / split leave",
    'aide_planning.txt_les_siens' => "Own only",
    'aide_planning.droit5_action' => "Read a cell's note",
    'aide_planning.txt_ses_notes' => "Own notes only",
    'aide_planning.txt_toutes_notes' => "All notes",
    'aide_planning.droit6_action' => "Move a BI from one technician to another",
    'aide_planning.astuces_li1' => "<b>Never leave a weekday empty</b> — even a small, normal day needs a shift and hours, otherwise the balance counter treats it as 7h \"due\" and 0h \"done\", i.e. -7h that looks unjustified.",
    'aide_planning.astuces_li2' => "<b>RTT ≠ Rest day ≠ Paid leave</b>: paid leave and rest days are neutral (0h due), but RTT still owes 7h — taking an RTT day genuinely debits your lead. Don't mix the three up if you want an accurate counter.",
    'aide_planning.astuces_li3' => "<b>A worked public holiday must be ticked AND have a shift</b>: ticking only \"Public holiday\" with no shift suggests you didn't work that day.",
    'aide_planning.astuces_li4' => "<b>Sick leave doesn't need hours entered</b>: just tick the box, the 7h is credited automatically.",
    'aide_planning.astuces_li5' => "<b>Check the \"Understand my hours balance\" bubble regularly</b> — it lists very precisely the days you still need to fill in, rather than guessing.",
    'aide_planning.astuces_li6' => "<b>Bulk-fill overwrites existing cells</b> over the chosen period: always check the dates before clicking \"Apply\".",
    'aide_planning.gloss1_dt' => "Shift",
    'aide_planning.gloss1_dd' => "The actual work pattern for a day: Morning, Afternoon, Night or Full day.",
    'aide_planning.gloss2_dt' => "Event",
    'aide_planning.gloss2_dd' => "An absence or an adjusted day: paid leave, RTT, sick leave, rest day, half-day leave, public holiday.",
    'aide_planning.gloss3_dt' => "On-call",
    'aide_planning.gloss3_dd' => "Information shown as a badge, with no effect on hours due/done.",
    'aide_planning.gloss4_dt' => "Hours due",
    'aide_planning.gloss4_dd' => "What the technician should have worked that day (7h, 3.5h or 0h depending on the cell ticked).",
    'aide_planning.gloss5_dt' => "Hours done",
    'aide_planning.gloss5_dd' => "The hours actually entered, plus the automatic 7h credit for a sick day.",
    'aide_planning.gloss6_dt' => "35h/week marker",
    'aide_planning.gloss6_dd' => "The cumulative hours due from April 1st up to today — the reference used to compare the hours balance.",
    'aide_planning.gloss7_dt' => "Annualized target",
    'aide_planning.gloss7_dd' => "The total hours to reach over the year (1607h by default), shown as a progress bar.",
    'aide_planning.gloss8_dt' => "Split leave",
    'aide_planning.gloss8_dd' => "Days granted by HR that reduce the annual target by 7h or 14h (Art. 6 of the annualization agreement).",
    'aide_planning.gloss9_dt' => "48h week",
    'aide_planning.gloss9_dd' => "A week where total hours entered reaches 48h or more, automatically reducing the target by 4h (Art. 3).",
    'aide_planning.gloss10_dt' => "Saturday leave",
    'aide_planning.gloss10_dd' => "A separate quota of 5 paid-leave days reserved for Saturdays, distinct from the 25 weekday paid-leave days.",
    'aide_planning.devnote_intro' => "Points noticed while reading the code, worth keeping in mind on the admin side:",
    'aide_planning.devnote_li1' => "The hours-balance logic (<code>referenceDuJour</code>, <code>calculerReferenceHeures35h</code>) is computed <b>client-side</b> from <code>planning_shifts</code> — no server-side recalculation, so any change to this rule must be mirrored in <code>planning.php</code>'s JS.",
    'aide_planning.devnote_li2' => "The annual target and split leave can be edited by the technician concerned themselves (not just an admin) — a deliberate code decision (\"everyone manages their own hours\"), worth reconfirming if HR policy changes.",
    'aide_planning.devnote_li3' => "Permission checks (editing others' cells, moving a BI) are done client-side only: the <code>save_shift</code>, <code>save_objectif</code> and <code>save_fractionnement</code> actions in <code>maintenance.php</code> don't recheck the role.",

    'aide_service.page_title_tag' => "Help - Services Portal",
    'aide_service.crumb_portail_services' => "Services Portal",
    'aide_service.crumb_aide' => "Help",
    'aide_service.badge_non_connecte' => "Not signed in",
    'aide_service.lien_se_connecter' => "Sign in",
    'aide_service.accueil_title' => "Home",
    'aide_service.hero_eyebrow' => "Services Portal Guide",
    'aide_service.hero_h1' => "Using the services portal",
    'aide_service.hero_tagline' => "Everything you need to report a breakdown, track your requests and share your ideas.",
    'aide_service.pill_updated' => "Updated on <b>09/04/2026</b>",
    'aide_service.pill_public' => "For <b>Production, Quality, Safety, HR, Logistics, Agronomy...</b>",
    'aide_service.toc_connexion' => "Signing in",
    'aide_service.toc_accueil' => "Your home page",
    'aide_service.toc_demande' => "Submitting a request",
    'aide_service.toc_suivi' => "Tracking my requests",
    'aide_service.toc_idees' => "Suggesting an idea",
    'aide_service.toc_annualisation' => "Leave, RTT & Annualization",
    'aide_service.toc_planning' => "Schedule (coming soon)",
    'aide_service.toc_astuces' => "Tips & pitfalls",
    'aide_service.toc_glossaire' => "Glossary",
    'aide_service.toc_faq' => "Frequently asked questions",
    'aide_service.connexion_lede' => "No email address or standard password: you select your department's name from a list, then enter the matching code.",
    'aide_service.shot_login_alt' => "GMAO sign-in page",
    'aide_service.shot_login_cap' => "The sign-in screen: a name, a code, a button.",
    'aide_service.co_step1_titre' => "Select your department's name",
    'aide_service.co_step1_desc' => "In the \"Who are you?\" dropdown, choose your department (e.g. \"S. Production\"), not a personal name.",
    'aide_service.co_step2_titre' => "Enter the department's general code",
    'aide_service.co_step2_desc' => "It's the same code for your whole team — different from the personal code you'll enter later in each request.",
    'aide_service.co_step3_titre' => "Click \"SIGN IN\"",
    'aide_service.co_step3_desc' => "You land directly on your home page, with the portal tiles.",
    'aide_service.callout_warn_code_perso' => "The department code just opens the portal. For <b>each request</b> you submit, an extra step will ask for your <b>name</b> and your own <b>personal code</b> — different from the department's sign-in code. This personal code acts as an electronic signature and also opens messaging on your tickets.",
    'aide_service.shot_erreur_alt' => "Error message: incorrect name or code",
    'aide_service.shot_erreur_cap' => "If you get an error, check the name selected, the code (no spaces) and Caps Lock.",
    'aide_service.accueil_lede' => "Once signed in, you land on a page with 4 tiles: this is the starting point for every function of the portal.",
    'aide_service.tile1_titre' => "New work request",
    'aide_service.tile1_desc' => "Report a breakdown or request a job from the maintenance team.",
    'aide_service.tile2_titre' => "Tracking my requests",
    'aide_service.tile2_desc' => "See the status of your tickets, and maintenance's replies (or refusals).",
    'aide_service.tile3_titre' => "Ideas to improve the GMAO",
    'aide_service.tile3_desc' => "Suggest an idea, a bug, or a missing feature.",
    'aide_service.tile4_titre' => "Help & FAQ",
    'aide_service.tile4_desc' => "This guide you're currently reading.",
    'aide_service.callout_tip_badge_rouge' => "A red badge can appear on <b>two</b> tiles: on <b>Tracking my requests</b>, it shows a number of new messages or replies from maintenance; on <b>Ideas to improve the GMAO</b>, it shows one or more unread admin replies on your submitted ideas.",
    'aide_service.demande_lede' => "The form works like a small guided wizard, in 4 steps shown in the left-hand column. Each step offers an illustrated help bubble, and <i class=\"fa-solid fa-circle-question\" style=\"color:var(--accent);\"></i> icons next to the most important fields open a detailed explanation.",
    'aide_service.shot_etape1_alt' => "Step 1 of the request form: identity and personal code",
    'aide_service.shot_etape1_cap' => "Step 1 — Identity: role, name, and personal code.",
    'aide_service.d_step1_titre' => "Identity",
    'aide_service.d_step1_desc' => "Choose your job / role, then your name, then enter your personal code (4 characters minimum).",
    'aide_service.d_step2_titre' => "Location",
    'aide_service.d_step2_desc' => "This isn't a simple dropdown: it's a real visual picker. A <b>\"Quick search\"</b> bar (\"Machine name, zone, area, plant...\") lets you type a machine name directly; otherwise, you browse through clickable tiles (Plant → Area → Line → Zone → Machine) with a breadcrumb to go back. Once the machine is chosen, a confirmation card is shown with a <b>\"Change machine\"</b> button if needed. If it doesn't exist in the list, choose <b>\"Other / Not listed\"</b> (only offered at the Machine level) and describe it in the next step.",
    'aide_service.d_step3_titre' => "Problem",
    'aide_service.d_step3_desc' => "Describe the breakdown (what, since when, severity) and indicate whether it's urgent — reserved for line stoppages or real hazards. The description must be <b>at least 10 characters</b>: a counter under the field guides you live (\"a bit more detail...\" then \"✓ that's clear!\" once the threshold is reached).",
    'aide_service.d_step4_titre' => "Submission",
    'aide_service.d_step4_desc' => "A full summary is shown before final submission to maintenance. You can still edit everything via \"Edit\". Once submitted, a <b>\"Ticket sent!\"</b> window confirms it, with two buttons: <b>\"New request\"</b> or <b>\"View tracking\"</b>.",
    'aide_service.shot_etape2_alt' => "Step 2: cascading location",
    'aide_service.shot_etape2_cap' => "Step 2 — Location",
    'aide_service.shot_etape3_alt' => "Step 3: problem description and urgency",
    'aide_service.shot_etape3_cap' => "Step 3 — Problem",
    'aide_service.callout_tip_envoyee' => "Once submitted, your request goes to maintenance immediately with the status <span class=\"pill pill-attente\"><span class=\"pill-dot\"></span>Pending</span>. Find it any time from the <b>\"Tracking my requests\"</b> tile on the home page.",
    'aide_service.suivi_lede' => "No need to call maintenance to know where your request stands: everything is visible on the \"Tracking my requests\" page, accessible from the home page.",
    'aide_service.shot_suivi_alt' => "Tracking panel for submitted requests",
    'aide_service.shot_suivi_cap' => "Stat tiles, filters and the ticket list — click a row to see the detail.",
    'aide_service.h3_5_statuts' => "The 5 statuses",
    'aide_service.pill_attente_label' => "Pending",
    'aide_service.pill_attente_desc' => "your request hasn't been validated by maintenance yet.",
    'aide_service.pill_afaire_label' => "To do",
    'aide_service.pill_afaire_desc' => "validated, a BI number has been assigned, it's waiting to be taken on.",
    'aide_service.pill_cours_label' => "In progress",
    'aide_service.pill_cours_desc' => "a technician is working on it.",
    'aide_service.pill_termine_label' => "Done",
    'aide_service.pill_termine_desc' => "the job is closed, a report has been written.",
    'aide_service.pill_refuse_label' => "Refused",
    'aide_service.pill_refuse_desc' => "maintenance didn't follow up; the refusal reason is shown in the ticket detail.",
    'aide_service.callout_lock_renommage' => "These 5 default names can be <b>renamed</b> by an administrator from Settings. If you see slightly different labels, that's normal — the order and meaning stay the same.",
    'aide_service.h3_vignettes' => "Tiles, search and filters",
    'aide_service.vignettes_p1' => "At the top of the page, <b>5 clickable tiles</b> mirror the 5 statuses with a counter — clicking one instantly filters the list. Below, a filter bar combines:",
    'aide_service.vf_li1' => "a <b>free-text search</b> (\"Search (description, machine, BI No.)...\") that searches the description, machine, BI number and location;",
    'aide_service.vf_li2' => "a filter by <b>requester</b> and a filter by <b>status</b>;",
    'aide_service.vf_li3' => "a specific <b>\"Unread messages\"</b> filter, to find every ticket awaiting your reading with one click;",
    'aide_service.vf_li4' => "a <b>\"Reset\"</b> button that clears all active filters.",
    'aide_service.vignettes_p2' => "The list is paginated in blocks of <b>8 tickets</b>, with \"Previous\" / \"Next\" buttons.",
    'aide_service.h3_carte' => "What a card or a ticket's detail shows",
    'aide_service.carte_lede' => "Beyond the status, several indicators can appear on a ticket:",
    'aide_service.tile_urgent_titre' => "Urgent",
    'aide_service.tile_urgent_desc' => "The priority chosen when the request was created.",
    'aide_service.tile_soustraite_titre' => "Subcontracted",
    'aide_service.tile_soustraite_desc' => "The job is given to an outside company; its name is shown.",
    'aide_service.tile_bris_titre' => "Equipment breakage",
    'aide_service.tile_bris_desc' => "The request concerns an accidental breakage.",
    'aide_service.tile_visserie_titre' => "Fastener check",
    'aide_service.tile_visserie_desc' => "A tightening check was requested or performed.",
    'aide_service.frise_p' => "A ticket's detail also shows a 4-step <b>progress timeline</b> — <i>Submitted → Validated → Taken on → Done</i> — a simplified view complementing the 5 detailed statuses above: each step already reached shows in green, and only the next expected step stays blue. The <b>\"Assigned technician\"</b> field is based on actual time entries (not just the technician assigned at creation): it shows \"No time entry logged\" until someone has logged time on it.",
    'aide_service.heures_p' => "As soon as at least one hour has been logged on the ticket, two extra pieces of information appear: <b>work hours</b> (the total time logged by maintenance) and the <b>completion date</b> (the day of the last time entry). If maintenance attached photos to the ticket, they also show in an <b>\"Attached photos\"</b> gallery — click a photo to enlarge it.",
    'aide_service.callout_tip_carnet' => "While the job is in progress, a <b>Logbook</b> can show interim notes left by the technician (e.g. \"part ordered, awaiting delivery\") — separate from the <b>final report</b>, which only appears once the ticket is Done.",
    'aide_service.h3_messagerie' => "Messaging",
    'aide_service.callout_tip_messagerie' => "A <b>Messaging</b> button lets you exchange directly with the technician about your request. The <b>\"Messaging Security\"</b> window asks you to identify yourself before writing: <b>reselect your name</b> from the \"Who are you?\" list <b>and</b> re-enter your personal code — not just the code alone. This is also how you're notified of a refusal.",
    'aide_service.callout_warn_badge_rouge' => "A red badge on a ticket or on the home tile signals an <b>unread message</b>: a reply from maintenance, or a refusal notification with its reason.",
    'aide_service.idees_lede' => "A missing feature, an annoying bug, a practical improvement? The <b>\"Ideas to improve the GMAO\"</b> tile is made for that.",
    'aide_service.i_step1_titre' => "Fill in the form",
    'aide_service.i_step1_desc' => "Your name, a category (feature, usability, bug, other), a short title and a description.",
    'aide_service.i_step2_titre' => "Track its status",
    'aide_service.i_step2_desc' => "Below the form, find every idea already submitted by your department, with its status: New, Under review, Accepted, Done, or Rejected.",
    'aide_service.i_step3_titre' => "Discuss with the administrator",
    'aide_service.i_step3_desc' => "Expanding an idea opens a real <b>discussion thread</b>: the administrator can reply to you, and you can reply back from a \"Write a reply to the administrator...\" field. Until a reply is given, you'll see \"No reply from the administrator yet.\"",
    'aide_service.callout_tip_nouveau' => "An unread admin reply shows a <b>\"NEW\"</b> badge on the idea concerned, and feeds the red badge on the <b>\"Ideas to improve the GMAO\"</b> tile on your home page.",
    'aide_service.annualisation_lede' => "Your paid leave, RTT, public holidays and sick leave are counted over a full year, not week by week — a principle that applies to every employee, not just the maintenance team. Here's the essential to know.",
    'aide_service.h3_1607h' => "The legal reference: 1607h per year",
    'aide_service.p_1607h' => "The legal working duration over a year is <b>1607h</b> (35h/week on average, including the solidarity day). This figure is calculated by already removing, from the year's 365 days, weekends, the <b>25 statutory paid-leave days</b> and <b>public holidays</b> — so these days are never counted a second time in the total hours worked.",
    'aide_service.tbl_th_type_jour' => "Day type",
    'aide_service.tbl_th_heures_dues' => "Hours due that day",
    'aide_service.tbl_th_debite' => "Debits your lead?",
    'aide_service.tbl_th_pourquoi' => "Why",
    'aide_service.row_cp_type' => "Paid leave",
    'aide_service.row_cp_heures' => "0h",
    'aide_service.row_cp_debite' => "No",
    'aide_service.row_cp_pourquoi' => "Already removed from the 1607h calculation: it isn't due, so it's never counted a second time.",
    'aide_service.row_demicp_type' => "Half-day paid leave",
    'aide_service.row_demicp_heures' => "3.5h",
    'aide_service.row_demicp_debite' => "No (half-day)",
    'aide_service.row_demicp_pourquoi' => "Same principle as paid leave, applied to a half-day.",
    'aide_service.row_rtt_type' => "RTT",
    'aide_service.row_rtt_heures' => "<b>7h</b>",
    'aide_service.row_rtt_debite' => "<b>Yes</b>",
    'aide_service.row_rtt_pourquoi' => "Unlike paid leave, an RTT day \"spends\" an hours credit already banked (you worked more than 35h on average some weeks): the day is still due normally, which genuinely debits 7h from your lead — that's the very principle of RTT.",
    'aide_service.row_repos_type' => "Rest day",
    'aide_service.row_repos_heures' => "0h",
    'aide_service.row_repos_debite' => "No",
    'aide_service.row_repos_pourquoi' => "The legal counterpart of a weekly rest day on a variable rotation — this day was never \"earned\" by extra hours, so nothing is due, and unlike RTT it spends no credit.",
    'aide_service.row_ferienontrav_type' => "Public holiday <i>(not worked)</i>",
    'aide_service.row_ferienontrav_heures' => "0h",
    'aide_service.row_ferienontrav_debite' => "No",
    'aide_service.row_ferienontrav_pourquoi' => "Like paid leave, already removed from the 1607h calculation.",
    'aide_service.row_ferietrav_type' => "Public holiday <i>(worked)</i>",
    'aide_service.row_ferietrav_heures' => "7h",
    'aide_service.row_ferietrav_debite' => "No (normal day)",
    'aide_service.row_ferietrav_pourquoi' => "Counts as an ordinary work day, compared against 7h — not a full \"bonus\" on hours done. The pay premium for a worked public holiday is a payroll matter, separate from this counter.",
    'aide_service.row_maladie_type' => "Sick leave",
    'aide_service.row_maladie_heures' => "7h",
    'aide_service.row_maladie_debite' => "No (neutral)",
    'aide_service.row_maladie_pourquoi' => "\"Neutralization\" principle: the 7h due is automatically credited as if the usual day had been worked, so as not to penalize an employee who cannot make up for an absence they didn't choose.",
    'aide_service.callout_warn_piege_rtt' => "<b>Common pitfall:</b> RTT isn't neutral like paid leave or a rest day — taking an RTT day genuinely debits 7h from your lead counter. Don't confuse it with a rest day, which stays at 0h and never debits anything.",
    'aide_service.callout_tip_suivi_detaille' => "Today, detailed tracking (team schedules, annual target, hours worked) happens on the maintenance team's screens, which the services portal doesn't have direct access to yet. To know your own situation (days taken, hours counter), check with your manager or HR.",
    'aide_service.callout_lock_pedagogique' => "This article is a general educational explanation, not a contractual document — if in doubt about your personal situation, your manager or HR remains the reference.",
    'aide_service.planning_lede' => "This function doesn't exist yet for the services portal — this section describes what's planned, as a preview.",
    'aide_service.callout_lock_pas_dispo' => "<b>Not yet available.</b> The maintenance team already has a schedule; the goal is to eventually open an equivalent tool to create and track your teams' schedules directly from the services portal.",
    'aide_service.planning_p2' => "The planned approach is the one already used on the maintenance side: a manual schedule, shown as a daily grid — one cell per day and per person. Clicking a cell would let you set:",
    'aide_service.planning_li1' => "a <b>worked shift</b> (morning, afternoon, night or full day), or",
    'aide_service.planning_li2' => "an <b>absence</b> (paid leave, RTT, sick leave, public holiday).",
    'aide_service.shot_planning_alt' => "Weekly schedule grid used by the maintenance team",
    'aide_service.shot_planning_cap' => "Preview of the grid used today by the maintenance team — the same approach is planned for the services portal.",
    'aide_service.callout_tip_bientot' => "This section will be completed with real instructions once the feature goes live for the services portal.",
    'aide_service.astuces_li1' => "<b>Remember your personal code well</b>: it's what proves it's you on every new request, and it opens messaging.",
    'aide_service.astuces_li2' => "<b>Be precise in the description</b>: the clearer it is, the faster maintenance can prioritize and step in.",
    'aide_service.astuces_li3' => "<b>A \"Pending\" request isn't forgotten</b>: it's simply waiting for maintenance to validate it — this delay depends on the team's workload.",
    'aide_service.astuces_li4' => "<b>Only use \"Urgent\" for a real stoppage or hazard</b>, so priorities stay meaningful for everyone.",
    'aide_service.astuces_li5' => "<b>A refused request isn't a mistake on your part</b>: the reason given always explains why, and you can create a new request if needed.",
    'aide_service.gloss1_dt' => "Personal code",
    'aide_service.gloss1_dd' => "A string of at least 4 characters that identifies you on every request, like an electronic signature.",
    'aide_service.gloss2_dt' => "Department code",
    'aide_service.gloss2_dd' => "The general code used by your whole team to sign in to the portal — different from the personal code.",
    'aide_service.gloss3_dt' => "BI",
    'aide_service.gloss3_dd' => "\"Bon d'Intervention\" (work order) — the number assigned to your request once validated by maintenance.",
    'aide_service.gloss4_dt' => "Refusal reason",
    'aide_service.gloss4_dd' => "The text entered by an administrator when a request isn't followed up, visible in the refused ticket's detail.",
    'aide_service.gloss5_dt' => "Logbook",
    'aide_service.gloss5_dd' => "The interim notes left by the technician while a ticket is still in progress — separate from the final closing report.",
    'aide_service.gloss6_dt' => "Subcontracted",
    'aide_service.gloss6_dd' => "A job given to an outside company rather than an in-house technician; its name is shown on the ticket.",
    'aide_service.faq_lede' => "Short answers, to move fast.",
    'aide_service.faq1_q' => "What is the personal code for?",
    'aide_service.faq1_li1' => "<b>1st request:</b> make up a code (4 characters minimum) — it will be remembered automatically, like a signature.",
    'aide_service.faq1_li2' => "<b>Following requests:</b> always re-enter the same code to confirm it's really you.",
    'aide_service.faq1_li3' => "It also identifies you to discuss with maintenance on your tickets (messaging).",
    'aide_service.faq2_q' => "I can't find the machine in the list",
    'aide_service.faq2_a' => "Choose <b>\"Other / Not listed\"</b> at the last location step, then describe the machine and its location precisely in the description field.",
    'aide_service.faq3_q' => "How do I describe my problem well?",
    'aide_service.faq3_li1' => "<b>What:</b> what's happening? (noise, leak, breakage, electrical fault...)",
    'aide_service.faq3_li2' => "<b>Since when:</b> just now, since this morning...",
    'aide_service.faq3_li3' => "<b>Severity:</b> is production stopped? Is there a hazard?",
    'aide_service.faq4_q' => "What's the difference between \"Normal\" and \"Urgent\"?",
    'aide_service.faq4_a' => "Choose <b>Urgent</b> only for a line stoppage or immediate hazard. For any routine job, leave it as <b>Normal</b> — maintenance prioritizes its jobs on that basis.",
    'aide_service.faq5_q' => "What do my tickets' statuses mean?",
    'aide_service.faq5_a' => "<span class=\"pill pill-attente\" style=\"margin:2px 4px 2px 0;\"><span class=\"pill-dot\"></span>Pending</span> your request has just been sent.<br>\n<span class=\"pill pill-afaire\" style=\"margin:2px 4px 2px 0;\"><span class=\"pill-dot\"></span>To do</span> validated and scheduled.<br>\n<span class=\"pill pill-cours\" style=\"margin:2px 4px 2px 0;\"><span class=\"pill-dot\"></span>In progress</span> a technician is working on it.<br>\n<span class=\"pill pill-termine\" style=\"margin:2px 4px 2px 0;\"><span class=\"pill-dot\"></span>Done</span> job closed, report available.<br>\n<span class=\"pill pill-refuse\" style=\"margin:2px 4px 2px 0;\"><span class=\"pill-dot\"></span>Refused</span> not accepted, reason visible in the detail.",
    'aide_service.faq6_q' => "How do I message the technician about a ticket?",
    'aide_service.faq6_a' => "Open the ticket from the <b>Tracking my requests</b> page, then click <b>Messaging</b>. You'll need to enter your name and personal code to send a message.",
    'aide_service.faq7_q' => "Why was my request refused?",
    'aide_service.faq7_a' => "An administrator chose not to follow up on it (duplicate, outside maintenance's scope...). The exact reason is always shown: open the ticket in <b>Tracking my requests</b> to read it in the red \"Refusal reason\" box.",
    'aide_service.faq8_q' => "How do I suggest an idea for the GMAO?",
    'aide_service.faq8_a' => "From the home page, click the <b>Ideas to improve the GMAO</b> tile. Fill in the short form (title, category, description): your idea is sent to the GMAO team, and you can track its status — and discuss with the administrator — directly on the same page.",
    'aide_service.faq9_q' => "How do I quickly find my tickets with an unread message?",
    'aide_service.faq9_a' => "On <b>Tracking my requests</b>, open the status filter and choose <b>\"Unread messages\"</b> — the list then only keeps tickets awaiting your reading.",
    'aide_service.callout_contact' => "A question not answered here, or a technical issue with the portal itself? Contact the maintenance / GMAO team directly.",

    'aide_annualisation.page_title_tag' => "Leave, RTT & Annualization - GMAO Help",
    'aide_annualisation.hero_h1' => "Leave, RTT, sick leave & Annualization",
    'aide_annualisation.hero_tagline' => "Understanding how your hours are counted over the year — and why, under the law.",
    'aide_annualisation.pill_version' => "Version <b>1.0</b>",
    'aide_annualisation.pill_updated' => "Updated on <b>08/18/2026</b>",
    'aide_annualisation.pill_ecrans' => "Screen concerned <b>Schedule</b>",
    'aide_annualisation.pill_sourced' => "Sourced from employment law",
    'aide_annualisation.toc_vue_ensemble' => "Overview",
    'aide_annualisation.toc_saisir' => "Taking paid leave, RTT, a public holiday…",
    'aide_annualisation.toc_formule' => "Where does 1607h come from?",
    'aide_annualisation.toc_traitement' => "How each absence is counted",
    'aide_annualisation.toc_ajustements' => "Target adjustments (split leave, 48h)",
    'aide_annualisation.toc_exemples' => "Worked examples",
    'aide_annualisation.toc_repere' => "The \"35h/week\" marker",
    'aide_annualisation.toc_faq' => "Frequently asked questions",
    'aide_annualisation.toc_glossaire' => "Glossary",
    'aide_annualisation.toc_sources' => "Legal sources",
    'aide_annualisation.vue_lede' => "<b>Annualization</b> of working time means counting your hours not week by week, but over a full year — here, from <b>April 1st to March 31st</b>. The target to reach over this period is <b>1607h</b> (unless a different individual agreement applies, adjustable in Settings). This article explains how this total is calculated, and above all how each type of non-worked day (leave, RTT, public holiday, sick leave) is treated.",
    'aide_annualisation.tbl1_th_ou' => "Where it happens",
    'aide_annualisation.tbl1_th_usage' => "What it's for",
    'aide_annualisation.row_planning_label' => "Schedule",
    'aide_annualisation.row_planning_desc' => "For each day, a click opens a window where you set a worked <b>shift</b> (morning / afternoon / night / full day) and/or an <b>event</b> (paid leave, half-day leave, RTT, sick leave, public holiday), with hours worked if needed.",
    'aide_annualisation.row_planning_annuel_label' => "Annual Schedule",
    'aide_annualisation.row_planning_annuel_desc' => "From the Schedule, a full month-by-month calendar with the detail of every day set, the cumulative total, the target (editable), split leave, and the help bubble detailing your hours balance.",
    'aide_annualisation.callout_tip_pas_calculer' => "You don't need to calculate anything yourself: set your days normally, the tool automatically applies the correct rules described below.",
    'aide_annualisation.saisir_lede' => "On the Schedule screen, click the cell for the relevant day on your row.",
    'aide_annualisation.s_step1_titre' => "Choose a shift (if you're working that day)",
    'aide_annualisation.s_step1_desc' => "Morning, afternoon, night or full day. Enter the hours worked if they differ from your usual schedule.",
    'aide_annualisation.s_step2_titre' => "Or choose an event (if you're absent)",
    'aide_annualisation.s_step2_desc' => "Paid leave, RTT, Rest day or Sick leave — these four boxes are mutually exclusive with a worked shift: you can't be \"on leave\" and \"on morning shift\" the same day. RTT and Rest day look similar but aren't interchangeable: see the next section for the difference.",
    'aide_annualisation.s_step3_titre' => "Special cases: half-day leave and public holiday",
    'aide_annualisation.s_step3_desc' => "Unlike the other events, <b>half-day paid leave</b> and <b>public holiday</b> are independent checkboxes that can be combined with a shift actually worked: for example a day where you work the morning and take a half-day off in the afternoon, or a public holiday where you still tick the \"Night\" shift because you worked that night.",
    'aide_annualisation.callout_warn_ferie_travaille' => "<b>Worked public holiday:</b> if you're exceptionally required to work a public holiday (common in industrial maintenance), tick the shift actually worked (morning/afternoon/night/full day) <b>and</b> also tick the <b>\"Public holiday\"</b> box, then enter the hours actually worked (e.g. 8h) — the tool will count them normally in your total, on top of the fact that this day wasn't due anyway (see below). Ticking \"Public holiday\" no longer unticks the chosen shift.",
    'aide_annualisation.formule_lede' => "1607h isn't a number picked at random: it's the result of a precise legal calculation, starting from a full year and removing everything that isn't a day of work owed.",
    'aide_annualisation.donut_num' => "228",
    'aide_annualisation.donut_label' => "days worked<br>out of 365",
    'aide_annualisation.leg_weekends_label' => "Weekends",
    'aide_annualisation.leg_weekends_jours' => "104 days",
    'aide_annualisation.leg_cp_label' => "Paid leave",
    'aide_annualisation.leg_cp_jours' => "25 days",
    'aide_annualisation.leg_feries_label' => "Public holidays",
    'aide_annualisation.leg_feries_jours' => "8 days",
    'aide_annualisation.leg_travailles_label' => "Days worked",
    'aide_annualisation.leg_travailles_jours' => "228 days",
    'aide_annualisation.donut_note' => "228 days worked × 7h = 1596h, + 7h solidarity day = <b>1607h</b> — the calculation detail is just below.",
    'aide_annualisation.formula_box' => "365 calendar days<br>\n<span class=\"op\">−</span> 104 days of weekly rest (52 Saturdays + 52 Sundays)<br>\n<span class=\"op\">−</span> 25 statutory paid-leave days<br>\n<span class=\"op\">−</span> 8 public holidays on average falling on a working day<br>\n<span class=\"res\">= 228 days actually worked</span><br>\n<br>\n228 days <span class=\"op\">×</span> 7h (35h/week ÷ 5 days) <span class=\"res\">= 1596h</span><br>\n<span class=\"op\">+</span> 7h solidarity day<br>\n<span class=\"res\">= 1607h</span>",
    'aide_annualisation.formule_p2' => "The important point: <b>paid leave and public holidays are already removed upfront</b> in this calculation. Your 1607h target is therefore not \"1607h of work plus your leave on top\" — the leave is already included. That's why counting it a second time (as extra hours worked) would artificially push you past the target.",
    'aide_annualisation.callout_law_samedi_p1' => "A team rule can add to the general law: on top of the <b>25 statutory paid-leave days</b>, some teams grant <b>5 extra days to be taken only on a Saturday</b> — these aren't 5 of the 25 normal days, but 5 additional days, i.e. <b>30 leave days total for the year</b>. In the tool, these two quotas are tracked separately in the Annual Schedule summary: \"Paid leave\" (/25) and \"Saturday leave\" (/5).",
    'aide_annualisation.callout_law_samedi_p2' => "This kind of rule usually exists in companies whose activity has a <b>peak period</b> (e.g. summer), where working Saturdays becomes possible or even necessary: these 5 extra days compensate for that availability by guaranteeing rest days set on that particular day. It isn't a rule from the Labor Code — the exact reason behind it can vary by organization, worth confirming with your management if in doubt. If your company applies these 30 days, remember to adjust your annual target accordingly from the Annual Schedule or Settings, since the default 1607h threshold assumes the legal base of 25 days.",
    'aide_annualisation.traitement_lede' => "This is the heart of the matter: each type of non-worked day follows a different rule, and it isn't arbitrary — each one comes from a precise legal principle.",
    'aide_annualisation.tbl2_th_type' => "Day type",
    'aide_annualisation.tbl2_th_total' => "Counts in my actual total",
    'aide_annualisation.tbl2_th_du' => "Is \"due\" (35h/week marker)",
    'aide_annualisation.tbl2_th_pourquoi' => "Why",
    'aide_annualisation.row2_cp_type' => "Paid leave",
    'aide_annualisation.row2_cp_total' => "<b>0h</b>",
    'aide_annualisation.row2_cp_du' => "No",
    'aide_annualisation.row2_cp_pourquoi' => "Already deducted in the 1607h calculation (see formula above) — a paid-leave day simply isn't due.",
    'aide_annualisation.row2_demicp_type' => "Half-day paid leave",
    'aide_annualisation.row2_demicp_total' => "<b>0h</b>",
    'aide_annualisation.row2_demicp_du' => "No (half a day)",
    'aide_annualisation.row2_demicp_pourquoi' => "Same principle as paid leave, applied to a half-day.",
    'aide_annualisation.row2_rtt_type' => "RTT",
    'aide_annualisation.row2_rtt_total' => "<b>0h</b>",
    'aide_annualisation.row2_rtt_du' => "<b>Yes (7h)</b>",
    'aide_annualisation.row2_rtt_pourquoi' => "An RTT day \"spends\" an hours credit already banked (you worked more than 35h on average, so the law owes you this day in exchange): the day is still due normally, which genuinely debits 7h from your lead — that's the very principle of RTT.",
    'aide_annualisation.row2_repos_type' => "Rest day",
    'aide_annualisation.row2_repos_total' => "<b>0h</b>",
    'aide_annualisation.row2_repos_du' => "No",
    'aide_annualisation.row2_repos_pourquoi' => "The legal counterpart of weekly rest for a variable rotation (Saturday/Sunday/any weekday depending on the schedule): this day was never \"earned\" by extra hours, so it isn't due — unlike RTT, it spends no credit.",
    'aide_annualisation.row2_ferienontrav_type' => "Public holiday <i>(not worked)</i>",
    'aide_annualisation.row2_ferienontrav_total' => "0h",
    'aide_annualisation.row2_ferienontrav_du' => "No",
    'aide_annualisation.row2_ferienontrav_pourquoi' => "Like paid leave, average public holidays are already removed in the 1607h calculation.",
    'aide_annualisation.row2_ferietrav_type' => "Public holiday <i>(worked)</i>",
    'aide_annualisation.row2_ferietrav_total' => "<b>Hours actually entered</b>",
    'aide_annualisation.row2_ferietrav_du' => "<b>Yes (7h)</b>",
    'aide_annualisation.row2_ferietrav_pourquoi' => "A worked public holiday counts as a normal day in the annualization: 8h worked stays 8h, compared against 7h due like any other day. The pay premium for a worked public holiday is a payroll matter, separate from this counter.",
    'aide_annualisation.row2_maladie_type' => "Sick leave",
    'aide_annualisation.row2_maladie_total' => "<b>7h (automatic credit)</b>",
    'aide_annualisation.row2_maladie_du' => "Yes (7h, like a normal day)",
    'aide_annualisation.row2_maladie_pourquoi' => "\"Neutralization\" principle upheld by the Court of Cassation in annualization matters: a sick-leave absence is counted as if the employee had worked their usual day, so as not to penalize them for time they cannot make up.",
    'aide_annualisation.callout_law_rtt_repos' => "<b>RTT and Rest day are not the same thing</b>, despite similar-sounding names. RTT compensates a weekly working time above 35h: taking it means spending an hours credit you've already banked, so the day stays \"due\" and debits 7h from your lead. A Rest day is simply the weekly rest every employee is entitled to — for teams on a variable rotation (morning/afternoon/night, with rest days falling on any day of the week depending on the cycle), it was never \"bought\" with extra hours, so it's never due.",
    'aide_annualisation.callout_tip_logique' => "Remember the logic in one sentence: <b>paid leave, half-day leave, Rest days and unworked public holidays are \"not due\" days</b> (they show up neither as a debt nor as a credit) — an actually-worked public holiday, on the other hand, becomes a normal day again compared against 7h, and an <b>RTT day stays due (it debits your lead)</b> since it spends a credit already earned — whereas <b>sick leave is neutralized \"as if\"</b> — it's credited so as not to create a debt you couldn't make up.",
    'aide_annualisation.ajustements_lede' => "Beyond the base 1607h, two situations provided for by the annualization agreement reduce the number of hours actually due over the year. They're set from the <b>Annual Schedule</b> window (click \"View full annual schedule\" from the scheduling window).",
    'aide_annualisation.tbl3_th_ajustement' => "Adjustment",
    'aide_annualisation.tbl3_th_effet' => "Effect on the target",
    'aide_annualisation.tbl3_th_qui' => "Who sets it",
    'aide_annualisation.row3_objectif_ajustement' => "Base annual target",
    'aide_annualisation.row3_objectif_effet' => "1607h by default",
    'aide_annualisation.row3_objectif_qui' => "You yourself or an admin, directly from the Annual Schedule (an admin can also set it for anyone from Settings).",
    'aide_annualisation.row3_fractionnement_ajustement' => "Split-leave days",
    'aide_annualisation.row3_fractionnement_effet' => "<b>−7h</b> (1 day) or <b>−14h</b> (2 days)",
    'aide_annualisation.row3_fractionnement_qui' => "You yourself or an admin, depending on the conditions under which the main leave was taken (Art. 6).",
    'aide_annualisation.row3_48h_ajustement' => "48h weeks",
    'aide_annualisation.row3_48h_effet' => "<b>−4h</b> per affected week, detected automatically",
    'aide_annualisation.row3_48h_qui' => "Nobody — calculated from the hours you enter.",
    'aide_annualisation.callout_law_fractionnement_p1' => "<b>Split leave</b> (Art. 6 of the agreement): if your main leave is taken in one go over at least 12 working days (including 2 weekly rest days), the law grants you extra rest days. Since it depends on the exact conditions under which the leave was taken, it can't be calculated automatically: HR determines whether you're entitled to 1 or 2 days, and an admin enters it in the tool — the displayed target then decreases by the corresponding number of hours.",
    'aide_annualisation.callout_law_fractionnement_p2' => "<b>48h weeks</b> (Art. 3, peak periods): weeks where you actually worked 48h or more grant 4h of rest, automatically deducted from the target — the tool detects these weeks itself from your entered hours, no extra entry is needed.",
    'aide_annualisation.callout_tip_plafond_cp' => "The agreement also caps continuous main leave at <b>12 working days</b> when it overlaps the period from <b>July 15 to September 30</b> (Art. 6). If you exceed this cap, an alert badge appears on the \"Paid leave\" tile of the annual summary, with the detail on hover.",
    'aide_annualisation.exemples_lede' => "To picture it clearly, here are four typical situations with the calculation detail. Technician \"Léa\" is a fictional example.",
    'aide_annualisation.ex1_titre' => "Example 1 — A week of paid leave",
    'aide_annualisation.ex1_desc' => "Léa takes 5 days of paid leave (Monday to Friday) over a week where she would normally have worked 5 days of 8h.",
    'aide_annualisation.ex1_calc' => "Actual week total: 5 × 0h = <b>0h</b><br>\n35h/week marker for this week: 5 × 0h due = <b>0h</b><br>\nGap: 0h — no false lag created.",
    'aide_annualisation.ex1_verdict' => "Taking leave is never a penalty",
    'aide_annualisation.ex2_titre' => "Example 2 — Three days of sick leave",
    'aide_annualisation.ex2_desc' => "Léa is on sick leave for 3 days, during a week where she was scheduled for 7h/day.",
    'aide_annualisation.ex2_calc' => "Actual total: 3 × 7h (automatic credit) = <b>+21h</b><br>\nMarker: 3 × 7h due = <b>21h</b><br>\nGap: 0h — she stays exactly on pace, despite not being able to work.",
    'aide_annualisation.ex2_verdict' => "No hours debt created by sick leave",
    'aide_annualisation.ex3_titre' => "Example 3 — A worked public holiday",
    'aide_annualisation.ex3_desc' => "On July 14th (a public holiday), Léa is exceptionally called in and works an 8h night shift: she ticks the \"Night\" shift <b>and</b> the \"Public holiday\" box, with 8h entered.",
    'aide_annualisation.ex3_calc' => "Actual total: <b>+8h</b> (the hours actually entered)<br>\nMarker: public holiday but actually worked, counted as a normal day = <b>7h</b><br>\nGap: <b>+1h</b> — just like any day where she'd worked 8h instead of 7h. The pay premium for this worked public holiday is still owed, but that's a payroll matter, not this counter.",
    'aide_annualisation.ex3_verdict' => "+1h ahead, like a normal day worked at 8h",
    'aide_annualisation.ex4_titre' => "Example 4 — Days of 8h instead of 7h",
    'aide_annualisation.ex4_desc' => "Léa works 20 \"full day\" shifts of 8h each (the team's usual shift), over a period where the legal marker expects 7h/day.",
    'aide_annualisation.ex4_calc' => "Actual total: 20 × 8h = <b>160h</b><br>\nMarker: 20 × 7h due = <b>140h</b><br>\nGap: <b>+20h ahead</b>, simply because her typical day is 8h and not 7h.",
    'aide_annualisation.ex4_verdict' => "This is normal and expected when the typical day is 8h",
    'aide_annualisation.repere_lede' => "On your annual progress bar, a small marker shows where you should stand <b>today</b> if you followed a steady 35h/week pace since April 1st.",
    'aide_annualisation.repere_li1' => "Monday to Friday, every day elapsed since April 1st is counted as due at a rate of 7h/day.",
    'aide_annualisation.repere_li2' => "Saturday and Sunday owe nothing by default (rest day) — <b>unless they're actually worked</b> (shift + hours entered), in which case they're compared against 7h exactly like a weekday. A Saturday worked for 8h therefore only gives +1h ahead, not +8h.",
    'aide_annualisation.repere_li3' => "Paid leave, half-day leave, Rest day and <i>unworked</i> public holiday aren't due (0h). For paid leave/half-day/public holiday, it's because they're already deducted from the 1607h threshold; a Rest day is simply the weekly rest of a variable rotation, never \"bought\" with extra hours. An <i>actually worked</i> public holiday becomes a normal day again compared against 7h — working a public holiday is no longer an automatic bonus, only the hours beyond 7h that day count as ahead.",
    'aide_annualisation.repere_li4' => "<b>RTT, on the other hand, stays due (7h)</b>: taking it spends an hours credit already banked, so it debits 7h from your lead that day — don't confuse it with the Rest day above, which stays neutral.",
    'aide_annualisation.repere_li5' => "Sick leave is still counted as due (7h), since it's credited identically in your actual total anyway — so the gap stays neutral.",
    'aide_annualisation.repere_p_avance_retard' => "\"Ahead\" means your actual total exceeds what the legal 35h/week pace expected of you by that date (most often because your days are 8h and not 7h). \"Behind\" means the opposite. Neither is a judgment — it's simply a pace indicator, to be compared against the final annual target (1607h), which is the only deadline that really counts.",
    'aide_annualisation.callout_tip_badge_jour' => "In the <b>Annual Schedule</b>, every past day shows a small \"+Xh\" (green) or \"-Xh\" (red) badge next to the hours entered, showing that specific day's gap against what was due. A summary of the same kind appears under each month's total.",
    'aide_annualisation.faq1_q' => "My hours total changed after an app update, why?",
    'aide_annualisation.faq1_a' => "Before August 2026, the tool automatically credited 7h for every paid-leave day taken (on top of any hours entered), to prevent taking leave from making you \"fall behind\" the target. This logic came from a good intention but was incorrect: paid leave is <b>already deducted</b> in the 1607h calculation (see the formula above), so crediting it on top artificially inflated the achieved total. Paid leave now counts as 0h, which is the legally correct value.",
    'aide_annualisation.faq2_q' => "Why isn't sick leave treated like paid leave?",
    'aide_annualisation.faq2_a' => "Because it isn't the same legal situation. Paid leave is a <i>scheduled</i> entitlement already removed from the 1607h threshold. Sick leave is an <i>unforeseen</i>, undergone absence — case law requires neutralizing it \"as if\" the employee had worked their usual schedule, so as not to create an hours debt they couldn't make up.",
    'aide_annualisation.faq3_q' => "Is RTT the same thing as paid leave?",
    'aide_annualisation.faq3_a' => "No, and their effect on your counter differs too. Paid leave is an entitlement set by law (25 days minimum per year) already deducted from the 1607h threshold: it's never due, no matter what. RTT doesn't exist in the Labor Code: it's a mechanism specific to the company agreement, compensating weekly working time above 35h by letting you \"take back\" the extra hours as a rest day — taking an RTT day therefore still counts as a due day (7h), which debits your lead accordingly.",
    'aide_annualisation.faq4_q' => "What's the difference between RTT and Rest day?",
    'aide_annualisation.faq4_a' => "RTT spends an hours credit you've already banked by working more than 35h on average: the day stays due (7h), so taking it reduces your lead. A Rest day is the legal counterpart of weekly rest — for a team on a variable rotation (morning/afternoon/night, with rest days falling on any day of the week depending on the cycle), this rest was never \"earned\" by extra hours, so it's never due (0h), without touching your RTT balance.",
    'aide_annualisation.faq5_q' => "I'm ahead / behind the marker, should I worry?",
    'aide_annualisation.faq5_a' => "No — it's simply an intermediate pace indicator, not an obligation. What really counts is the total over the full year (April 1st to March 31st) compared against the 1607h target, shown at the top of the Annual Schedule window.",
    'aide_annualisation.gloss1_dt' => "Annualization",
    'aide_annualisation.gloss1_dd' => "Counting working time over a one-year period (here: April 1st to March 31st) rather than week by week.",
    'aide_annualisation.gloss2_dt' => "Paid leave",
    'aide_annualisation.gloss2_dd' => "Statutory leave day, accrued at a rate of 2.5 working days per month worked, i.e. 25 days/year minimum.",
    'aide_annualisation.gloss3_dt' => "RTT",
    'aide_annualisation.gloss3_dd' => "\"Réduction du Temps de Travail\": a rest day compensating a weekly schedule above 35h, defined by company agreement (not directly by law). Spends an hours credit already earned: still counted as due (7h) in the tool.",
    'aide_annualisation.gloss4_dt' => "Rest day",
    'aide_annualisation.gloss4_dd' => "Legal counterpart of weekly rest for a variable rotation (rest days falling on any day of the week depending on the morning/afternoon/night cycle). Unlike RTT, never due (0h) and spends no credit.",
    'aide_annualisation.gloss5_dt' => "Public holiday",
    'aide_annualisation.gloss5_dd' => "A day listed by law (January 1st, May 1st, July 14th…) where work is in principle not due, unless activity is exceptionally maintained.",
    'aide_annualisation.gloss6_dt' => "\"As if\" neutralization",
    'aide_annualisation.gloss6_dd' => "Case-law principle: a justified, paid absence (sick leave) is counted as if the scheduled hours had been worked, so as not to penalize the employee.",
    'aide_annualisation.gloss7_dt' => "Solidarity day",
    'aide_annualisation.gloss7_dd' => "7h of extra unpaid work per year, added to the 1607h calculation, intended to fund support for elderly and disabled people.",
    'aide_annualisation.gloss8_dt' => "35h/week marker",
    'aide_annualisation.gloss8_dd' => "Intermediate pace indicator on the progress card: what you \"should\" have accumulated by today following a steady pace.",
    'aide_annualisation.gloss9_dt' => "Split leave",
    'aide_annualisation.gloss9_dd' => "Extra rest days granted when the main leave is taken continuously over 12 working days or more (Art. 6): 1 or 2 days depending on conditions, at HR's discretion.",
    'aide_annualisation.sources_lede' => "The rules described in this article are based on the official 1607h calculation and the Court of Cassation's case law on annualization/modulation of working time.",
    'aide_annualisation.source1' => "Calcul des 1607 heures et annualisation — guide DRH 2026",
    'aide_annualisation.source2' => "RTT et congés payés : quelles différences ?",
    'aide_annualisation.source3' => "Absence maladie et heures supplémentaires — méthode de calcul (Cour de cassation)",
    'aide_annualisation.source4' => "Arrêt maladie et annualisation : les heures supplémentaires",
    'aide_annualisation.callout_lock_pedagogique' => "This article is an educational explanation, not a contractual document. If in doubt about your personal situation, check with HR or your maintenance manager.",
    'aide_annualisation.devnote_li1' => "Actual total calculation: <code>planning.php</code>, <code>annualisation.php</code>, <code>stats_tech.php</code> — <code>SUM(heures) + 7h if poste='maladie'</code>. Paid leave/RTT/public holiday no longer credit anything since the August 2026 fix (previously +7h/+3.5h, incorrect since already deducted from the 1607h threshold).",
    'aide_annualisation.devnote_li2' => "35h/week marker: <code>calculerReferenceHeures35h(tech)</code> in <code>planning.php</code>, day by day via <code>referenceDuJour(shift, dStr, isWeekend)</code>. Monday-Friday: 7h due by default, 0h if paid leave/Rest day or <code>jour_ferie</code> ticked <i>and not worked</i> (<code>estTravaille()</code> checks the shift isn't an actually-worked one), 3.5h if half-day leave. <b>RTT is no longer in this exclusion list since the August 2026 fix</b>: it stays due at 7h like a normal day, which genuinely debits the lead when taken (it spends an hours credit already earned, unlike Rest day which spends none). Saturday-Sunday: 0h by default (<code>ligneVide()</code>), unless actually set/worked, in which case the same rules as a weekday apply. A worked public holiday (shift + hours, <code>jour_ferie=1</code>) is therefore no longer \"not due\": it's compared against 7h like a normal day. Sick leave stays normally due (not in the exclusion list) since it's credited identically on the actual-total side anyway. The same <code>referenceDuJour()</code> also feeds the daily \"+Xh/-Xh\" badges (shown as soon as the row isn't <code>ligneVide()</code>, including an RTT day with no hours entered) and <code>renderAnnualGrid()</code>'s monthly summary.",
    'aide_annualisation.devnote_li3' => "\"Rest day\" (shift <code>repos</code>, category <code>evenement</code>, auto-migrated into <code>planning_postes</code> by <code>planning.php</code> and <code>parametres.php</code>): added in August 2026 for teams on a variable rotation, where weekly rest doesn't systematically fall on the weekend. Treated like paid leave in <code>referenceDuJour()</code> (0h due, weekday and weekend), but stays a category distinct from RTT in the summary (<code>recap.repos</code>) — the two share no counter.",
    'aide_annualisation.devnote_li4' => "Since the August 2026 fix, \"Public holiday\" is no longer an exclusive value of <code>poste</code> but an independent checkbox (column <code>planning_shifts.jour_ferie</code>, same mechanism as <code>demi_conge</code>): can be ticked on top of an actually-worked shift (morning/afternoon/night/full day) without clearing it. Automatic migration on load: old <code>poste='jour_ferie'</code> rows become <code>poste=NULL, jour_ferie=1</code>.",
    'aide_annualisation.devnote_li5' => "Fixed paid-leave quotas (25 days/year + 5 dedicated Saturdays, i.e. 30, additive and not a subset): encoded in <code>renderAnnualGrid()</code>'s summary, not a generic legal rule. Paid leave taken on a Saturday only spends the <code>cpSamedi</code> quota, never the <code>cp</code> quota. Half-day leave no longer has a separate tile since the August 2026 fix: it credits 0.5 day directly into <code>cp</code> or <code>cpSamedi</code> depending on the day.",
    'aide_annualisation.devnote_li6' => "Effective target (<code>getObjectifEffectif(tech)</code> in <code>planning.php</code>) = <code>utilisateurs.objectif_heures_annuel</code> − 7h/day of split leave (<code>planning_fractionnement</code>, table per reference period, editable by the technician concerned or an admin via <code>maintenance.php?action=save_fractionnement</code>) − 4h per ISO week where <code>SUM(heures)</code> ≥ 48 (<code>calculerSemaines48h()</code>, automatic detection, no dedicated entry). The base target is editable directly from the Annual Schedule by the technician concerned or an admin (<code>action=save_objectif</code>), in addition to Settings. The 35h/week marker (<code>calculerReferenceHeures35h</code>) also deducts split leave and 48h weeks, not just the final target.",
    'aide_annualisation.devnote_li7' => "Paid-leave cap alert (Art. 6, 12 consecutive working days max between 07/15 and 09/30): detected in <code>renderAnnualGrid()</code> by counting consecutive calendar days with <code>poste='cp'</code>, a Sunday without paid leave not breaking the streak (weekly rest day, never worked). Badge shown only on the \"Paid leave\" tile of the summary.",

    'aide_parc_machine.page_title_tag' => "Manage the Machine Fleet - GMAO Help",
    'aide_parc_machine.hero_tagline' => "The site's full equipment tree — the foundation every other page relies on.",
    'aide_parc_machine.pill_version' => "Version <b>1.2</b>",
    'aide_parc_machine.pill_updated' => "Updated on <b>08/30/2026</b>",
    'aide_parc_machine.pill_ecrans' => "Screen concerned <b>Machine Fleet</b>",
    'aide_parc_machine.pill_lecture' => "Read access for everyone, admin edits",
    'aide_parc_machine.toc_vue_ensemble' => "Overview",
    'aide_parc_machine.toc_explorer' => "Exploring the tree",
    'aide_parc_machine.toc_ajouter' => "Adding a machine",
    'aide_parc_machine.toc_modifier' => "Editing, moving, reordering",
    'aide_parc_machine.toc_renommer' => "Renaming a plant, area, line or zone",
    'aide_parc_machine.toc_supprimer' => "Deleting a machine",
    'aide_parc_machine.toc_selection_multiple' => "Multi-select",
    'aide_parc_machine.toc_schema_usine' => "Plant C Diagram & equipment records",
    'aide_parc_machine.toc_categories_schema' => "Diagram visual categories",
    'aide_parc_machine.toc_source_verite' => "Why this page is central",
    'aide_parc_machine.toc_droits' => "Who can do what",
    'aide_parc_machine.toc_astuces' => "Tips & pitfalls",
    'aide_parc_machine.toc_glossaire' => "Glossary",
    'aide_parc_machine.vue_lede' => "The <b>Machine Fleet</b> is the full tree of every piece of equipment on site, organized into 5 levels. It's the <b>single source of truth</b>: it's what feeds the location dropdowns everywhere else in the application (creating a work order, preventive plan, schedule...).",
    'aide_parc_machine.tree_usine' => "Plant",
    'aide_parc_machine.tree_secteur' => "Area",
    'aide_parc_machine.tree_ligne' => "Line",
    'aide_parc_machine.tree_zone' => "Zone",
    'aide_parc_machine.tree_machine' => "Machine",
    'aide_parc_machine.vue_p2' => "At the top of the page, a subtitle summarizes the totals: <i>\"X plant(s) · X areas · X lines · X zones · X machines\"</i>, and every node in the tree shows a badge with the number of machines it contains.",
    'aide_parc_machine.shot_arbre_alt' => "Machine Fleet tree with search and equipment-type filters",
    'aide_parc_machine.shot_arbre_cap' => "The full Machine Fleet tree: search, type filter chips, and the Plant (purple) / Zone (orange) nodes with their counter.",
    'aide_parc_machine.callout_tip_lecture_seule' => "A technician or maintenance team member sees exactly the same tree as an admin (full view), but in <b>read-only</b> mode — a <b>\"Read-only\"</b> badge replaces the add button in the top right.",
    'aide_parc_machine.explorer_lede' => "Every role has the same navigation tools.",
    'aide_parc_machine.card_recherche_titre' => "Search",
    'aide_parc_machine.card_recherche_desc' => "Type the name of a machine, a zone, a line... Results are highlighted in yellow, and parent nodes expand automatically to reveal them.",
    'aide_parc_machine.card_filtrer_titre' => "Filter by equipment type",
    'aide_parc_machine.card_filtrer_desc' => "Chips under the search bar (Mechanical, Electrical, Refrigeration...) let you isolate machines of a single type. Combines with search.",
    'aide_parc_machine.card_deplier_titre' => "Expand / collapse all",
    'aide_parc_machine.card_deplier_desc' => "Two dedicated buttons. Each node's state (open/closed) is remembered on your device from one visit to the next.",
    'aide_parc_machine.card_chevrons_titre' => "Clickable chevrons",
    'aide_parc_machine.card_chevrons_desc' => "Each node expands/collapses individually with a click on its chevron.",
    'aide_parc_machine.ajouter_lede' => "<b>\"+ Add a machine\"</b> button in the top right, or the <b>\"+\"</b> icon shown when hovering a zone in the tree (pre-fills its location directly). Opens a side panel.",
    'aide_parc_machine.a_step1_titre' => "Choose the location",
    'aide_parc_machine.a_step1_desc' => "Plant/site → Area → Line → Zone, in a cascade. Each list offers the already-existing values <b>+ a \"+ New...\" option</b> that opens a free-text field to create a node on the fly. A preview of the full path is shown live under the fields.",
    'aide_parc_machine.a_step2_titre' => "Name the machine",
    'aide_parc_machine.a_step2_desc' => "Required field.",
    'aide_parc_machine.a_step3_titre' => "Choose an equipment type (optional)",
    'aide_parc_machine.a_step3_desc' => "Shown as clickable tiles rather than a dropdown — one tile per already-known type, plus an <b>\"Other\"</b> tile to create a new one on the fly.",
    'aide_parc_machine.a_step4_titre' => "Save",
    'aide_parc_machine.a_step4_desc' => "The 4 location fields and the name are all required — otherwise: \"Please fill in all fields.\"",
    'aide_parc_machine.callout_tip_reouvre' => "After saving, the panel <b>reopens automatically, pre-filled with the same location</b> — handy for adding several machines in a row in the same zone without re-entering everything.",
    'aide_parc_machine.card_modifier_titre' => "Editing a machine",
    'aide_parc_machine.card_modifier_desc' => "Pencil icon when hovering a machine row, or click the machine directly. Same form as adding one, pre-filled.",
    'aide_parc_machine.card_glisser_titre' => "Drag and drop",
    'aide_parc_machine.card_glisser_desc' => "Freely reorganize the order of machines, zones, lines and areas by drag and drop. Moving a machine to another zone genuinely changes its location in the database.",
    'aide_parc_machine.callout_tip_historique_suit' => "Editing a machine (name, or location) <b>automatically carries the change over to its work-order history</b> (BI table): the history follows the machine, it doesn't break.",
    'aide_parc_machine.renommer_lede' => "Pencil icon when hovering the row of the relevant node (not a machine, but a grouping level). Opens the <b>\"Rename\"</b> window.",
    'aide_parc_machine.callout_tip_renommage_masse' => "Renaming a plant, an area or a zone <b>renames every machine it contains at once</b>, and updates the corresponding work-order history. It's a bulk rename, not just cosmetic.",
    'aide_parc_machine.renommer_p2' => "A node (area, line, zone) with no machine left attached <b>disappears automatically</b> from the tree — there's no need to delete it explicitly.",
    'aide_parc_machine.supprimer_lede' => "Trash icon when hovering a machine row, then confirmation in a dedicated window.",
    'aide_parc_machine.callout_warn_suppression' => "<b>No check is performed</b> on the related history: deleting a machine doesn't delete its past jobs or preventive plans, but they become \"orphaned\" — the machine will no longer appear in dropdowns on other pages, while its history stays viewable wherever it was already recorded. Think twice before deleting a machine with active history: a simple rename is almost always preferable.",
    'aide_parc_machine.selection_lede' => "<b>\"Multi-select\"</b> button at the top of the page: shows a checkbox in front of every machine.",
    'aide_parc_machine.selection_p2' => "Ticking one or more machines shows a floating bar at the bottom of the screen, with the <b>\"Assign a type...\"</b> button — handy for bulk-reclassifying every machine of a given type that didn't have one yet, rather than editing them one by one. Here too, an <b>\"Other\"</b> tile lets you enter a type name that doesn't exist yet in a small field that appears just below.",
    'aide_parc_machine.schema_lede' => "<b>\"Plant C Diagram\"</b> button at the top of the page (visible to everyone, admin and technician alike): opens an interactive view of Line C, with every machine and every numbered screw/belt clickable.",
    'aide_parc_machine.card_tri_titre' => "Sorting room",
    'aide_parc_machine.card_tri_desc' => "Harrow, beaters, Sinex, Aero 1/2, vibrating units, shredder, and the 36 numbered screws, shown as two flow lines: \"product line\" (screws 1 to 25) and \"waste line\" (screws 26 to 36).",
    'aide_parc_machine.card_cond_titre' => "Packing / Palletizing",
    'aide_parc_machine.card_cond_desc' => "Doser, bagging machine, sealers, metal detector, scale, labeler, robot, wrapper... and the 19 Pattyn belts (T1 to T19).",
    'aide_parc_machine.schema_p2' => "Clicking a machine or a number opens its <b>equipment record</b>, with 6 tabs:",
    'aide_parc_machine.li_fiche_technique' => "<b>Technical sheet</b>: at the top, a panel shows the name of the linked Machine Fleet machine along with its full location (plant / area / line / zone), fetched automatically — never re-entered by hand. Then come the motor, gearbox, belt and front/rear bearing references, motor and cable numbers, and the <b>PLC tag</b> (the number used on electrical/automation diagrams, e.g. <code>201052</code>) — distinct from the mechanical number (screw/belt).",
    'aide_parc_machine.li_historique_bi' => "<b>BI history</b>: if the record is linked to a Machine Fleet machine, the list of work orders already carried out shows automatically, with each card showing the job type, any breakage or subcontracted job, and a preview of the report. Clicking a card opens the full work report; an admin can reopen an already-closed one from there.",
    'aide_parc_machine.li_interventions' => "<b>Interventions</b>: a free-text log, for noting a job even without going through a formal work order.",
    'aide_parc_machine.li_documentation' => "<b>Documentation</b>: upload technical documents (PDF, images, Word, Excel) from any device on the network — stored per item. Admin-only. Files up to 300 MB.",
    'aide_parc_machine.li_devis' => "<b>Quotes</b>: same principle as Documentation (same formats, same 300 MB), to centralize quotes received for this machine — also admin-only.",
    'aide_parc_machine.li_aide_pannes' => "<b>Help / Known faults</b>: free-text notes (fault observed + fix) to keep track of recurring faults and their remedy, viewable by the whole team.",
    'aide_parc_machine.callout_tip_plan_reprend' => "The diagram reproduces the exact position, shape and color of the original technical PowerPoint diagrams.",
    'aide_parc_machine.callout_lock_droits_fiche' => "Both admin and technician see the linked Machine Fleet machine (name + location) and can both fill in the technical sheet and add an intervention. Only an <b>admin</b> can upload or delete a document/quote, and link/unlink a record to a Machine Fleet machine (for automatic BI history).",
    'aide_parc_machine.h3_modifier_plan' => "Editing the diagram itself (admin)",
    'aide_parc_machine.modifier_plan_p' => "<b>\"Edit the diagram\"</b> button at the top of the diagram (admin-only): every shape becomes movable and resizable directly with the mouse (or a finger on tablet). A <b>left click</b> selects a shape to move/resize it; a <b>right click</b> (or adding a new shape) also opens the <b>\"Shape properties\"</b> panel:",
    'aide_parc_machine.li_texte_forme' => "<b>Text</b> shown on the shape, and <b>Shape</b> (a large library: rectangles, circles, triangles, polygons, arrows, flowchart symbols...).",
    'aide_parc_machine.li_categorie' => "<b>Category</b>: <code>Free properties</code> (default — all settings below stay visible and directly editable) or one of the categories created in <a href=\"#categories-schema\">Settings</a> (Screw, Conveyor...). Choosing a category instantly applies its colors and starting values, then <b>collapses the detailed settings</b> behind a <b>\"Show advanced settings\"</b> button — open it to adjust this specific shape without touching the others. The <i class=\"fa-solid fa-rotate\"></i> icon next to the menu reapplies the values of the already-selected category (useful if its colors were changed in the meantime in Settings).",
    'aide_parc_machine.li_couleurs' => "<b>Colors</b>: fill / border / text, a \"No border\" checkbox, a \"Gradient\" checkbox (2 colors, with a direction choice) and <b>Effect</b> (None, Shadow, Bevel, Inset, Glow).",
    'aide_parc_machine.li_taille_rotation' => "<b>Size &amp; rotation</b>: width, height, text size, <b>Shape rotation</b> and <b>Text rotation</b> (two independent settings).",
    'aide_parc_machine.li_comportement' => "<b>Behavior</b>: <b>Clickable</b> (untick to turn a machine into a plain decorative element, or tick the reverse on a background element to give it an equipment record) and the front/background order.",
    'aide_parc_machine.li_supprimer_forme' => "<b>Delete this shape</b> — also removes its equipment record, interventions and documents.",
    'aide_parc_machine.p_ajouter_forme' => "<b>\"+ Add a shape\"</b> button to create a brand-new element from scratch. Every change saves automatically (no separate \"Save\" button).",
    'aide_parc_machine.callout_tip_rotation_texte' => "The text on a shape <b>taller than it is wide</b> (a screw, for instance) automatically rotates to read bottom-to-top (head tilted left), whether you type a width/height or resize with the mouse — and switches back to horizontal if the shape becomes wider than tall again. This automation never overrides a manually chosen text rotation.",
    'aide_parc_machine.categories_lede' => "In <b>Settings → Diagram categories</b> (or via the <i class=\"fa-solid fa-gear\"></i> icon next to \"+ Add a shape\" in the diagram, which leads there in one click), the admin can create reusable categories — <i>Screw</i>, <i>Waste screw</i>, <i>Conveyor</i>... — to style every shape of a given type at once rather than setting up each shape one by one.",
    'aide_parc_machine.categories_p2' => "A category groups two types of settings, with deliberately different behavior for each:",
    'aide_parc_machine.li_apparence' => "<b>Appearance</b> (fill color, gradient, border, effect): <b>always synced</b>. Changing these colors in Settings instantly carries the change over to every shape already assigned to this category.",
    'aide_parc_machine.li_valeurs_depart' => "<b>Starting values</b> (shape, size, rotation, default text, clickable): applied <b>only once</b>, the moment the category is chosen on a shape in the diagram. A later change to these values in Settings never modifies shapes already assigned — their individual settings (size adjusted by hand, rotation, text specific to each machine...) are therefore always preserved.",
    'aide_parc_machine.callout_tip_exemple_vis' => "Handy in practice: change the color of a \"Waste screw\" category in Settings, and the 36 screws already set to \"Waste screw\" on the diagram change color all at once — without losing the sizes and rotations adjusted individually for each.",
    'aide_parc_machine.source_lede' => "The Machine Fleet is the <b>single source</b> of the location dropdowns used elsewhere in the application.",
    'aide_parc_machine.route_tag' => "Used by",
    'aide_parc_machine.route1_titre' => "Creating a BI / request",
    'aide_parc_machine.route1_desc' => "The Plant → Area → Zone → Machine cascade, in <a href=\"aide_ot.php\">Entry &amp; History</a> and the request portal, comes directly from here.",
    'aide_parc_machine.route2_titre' => "Preventive & Schedule",
    'aide_parc_machine.route2_desc' => "Preventive maintenance plans and some Schedule forms rely on the same machine list.",
    'aide_parc_machine.callout_warn_absente' => "If a machine <b>doesn't appear</b> in a dropdown elsewhere in the application, it's almost always because it doesn't exist — or no longer exists — in the Machine Fleet. The fix is to come and create it here first.",
    'aide_parc_machine.tbl_th_action' => "Action",
    'aide_parc_machine.tbl_th_technicien' => "Technician",
    'aide_parc_machine.tbl_th_admin' => "Admin",
    'aide_parc_machine.droit1_action' => "View the tree, search, filter",
    'aide_parc_machine.droit2_action' => "Add / edit / move a machine",
    'aide_parc_machine.droit3_action' => "Rename a plant / area / line / zone",
    'aide_parc_machine.droit4_action' => "Delete a machine",
    'aide_parc_machine.droit5_action' => "Bulk-assign a type",
    'aide_parc_machine.astuces_li1' => "<b>Prefer renaming over deleting + recreating</b> a machine or a zone: renaming keeps all the history, deleting disconnects it.",
    'aide_parc_machine.astuces_li2' => "<b>\"+ New...\"</b> in the location fields creates a real node as soon as a machine is attached to it — no need to create an \"empty area\" beforehand.",
    'aide_parc_machine.astuces_li3' => "<b>A node with no machine disappears on its own</b> from the tree — that's expected, not a bug.",
    'aide_parc_machine.astuces_li4' => "<b>Multi-select</b> is only for bulk-assigning an equipment type — there's no bulk delete.",
    'aide_parc_machine.gloss1_dt' => "Node",
    'aide_parc_machine.gloss1_dd' => "A level of the tree (a plant, an area, a line or a zone).",
    'aide_parc_machine.gloss2_dt' => "Equipment type",
    'aide_parc_machine.gloss2_dd' => "A technical category (Mechanical, Electrical...), configurable from Settings.",
    'aide_parc_machine.gloss3_dt' => "Source of truth",
    'aide_parc_machine.gloss3_dd' => "The reference data other pages depend on — here, the Machine Fleet for every location.",
    'aide_parc_machine.devnote_intro' => "Points noticed while reading the code, worth keeping in mind on the admin side:",
    'aide_parc_machine.devnote_li1' => "There's no real foreign key between <code>machines</code> and <code>taches</code>/preventive plans — the link is done by text matching (plant+area+zone+name). Deleting a machine therefore breaks nothing technically, but orphans its history from the reference data.",
    'aide_parc_machine.devnote_li2' => "Renaming a <b>line</b> doesn't update <code>taches</code> (this table has no <code>ligne</code> column) — only plant/area/zone/machine are propagated.",
    'aide_parc_machine.devnote_li3' => "An equipment type created \"on the fly\" via the \"Other\" tile isn't added to the <code>types_equipement</code> reference table — it only shows up as long as at least one machine uses it, with a generic icon.",

    'aide_sous_traitants.page_title_tag' => "Manage Subcontractors - GMAO Help",
    'aide_sous_traitants.hero_tagline' => "Schedule an outside company, track their presence on site, and keep their Prevention Plans up to date.",
    'aide_sous_traitants.pill_version' => "Version <b>1.0</b>",
    'aide_sous_traitants.pill_updated' => "Updated on <b>08/20/2026</b>",
    'aide_sous_traitants.pill_ecrans' => "Screen concerned <b>Subcontractors</b>",
    'aide_sous_traitants.pill_roles' => "All roles (directory admin-only)",
    'aide_sous_traitants.toc_vue_ensemble' => "Overview",
    'aide_sous_traitants.toc_planifier' => "Scheduling a job",
    'aide_sous_traitants.toc_presence' => "Tracking presence on site",
    'aide_sous_traitants.toc_cloturer' => "Closing a job",
    'aide_sous_traitants.toc_pdp' => "The Prevention Plan (PdP)",
    'aide_sous_traitants.toc_annuaire' => "The company directory",
    'aide_sous_traitants.toc_historique' => "History",
    'aide_sous_traitants.toc_droits' => "Who can do what",
    'aide_sous_traitants.toc_astuces' => "Tips & pitfalls",
    'aide_sous_traitants.toc_glossaire' => "Glossary",
    'aide_sous_traitants.vue_lede' => "The <b>Subcontractors</b> screen is the dashboard for every outside company working on site: who's scheduled, who's physically present right now, and the history of what's already been done. A subcontracted job is still a <b>work order (BI)</b> like any other — it shows up with the same numbers and the same detail as ones created from <a href=\"aide_ot.php\">Entry &amp; History</a>, just with an extra \"subcontracted\" label.",
    'aide_sous_traitants.vue_p2' => "Three areas structure the page:",
    'aide_sous_traitants.card_planification_titre' => "Scheduling",
    'aide_sous_traitants.card_planification_desc' => "The table of upcoming or paused jobs, with their Prevention Plan.",
    'aide_sous_traitants.card_sursite_titre' => "Currently on site",
    'aide_sous_traitants.card_sursite_desc' => "Real-time cards for every company physically present.",
    'aide_sous_traitants.card_historique_titre' => "History",
    'aide_sous_traitants.card_historique_desc' => "Jobs already closed (accessible via a dedicated button).",
    'aide_sous_traitants.vue_p3' => "Three counters at the top of the page give an immediate status check: <b>Companies on site</b>, <b>Scheduled jobs</b>, and <b>Missing / Expired PdP</b> (an alert worth watching closely, see below).",
    'aide_sous_traitants.shot_dashboard_alt' => "Subcontractors dashboard: counters, scheduling and on-site presence",
    'aide_sous_traitants.shot_dashboard_cap' => "The full dashboard: the 3 counters, scheduling, and the \"Currently on site\" panel.",
    'aide_sous_traitants.planifier_lede' => "<b>\"NEW JOB\"</b> button at the top of the scheduling table.",
    'aide_sous_traitants.p_step1_titre' => "Tick one or more companies",
    'aide_sous_traitants.p_step1_desc' => "The \"Outside Company\" list offers checkboxes. Ticking several companies creates <b>a separate job per company</b>, each with its own BI number.",
    'aide_sous_traitants.p_step2_titre' => "Enter the type, date and time",
    'aide_sous_traitants.p_step2_desc' => "Type (Project / Preventive / Curative), job date, expected arrival time (8am by default).",
    'aide_sous_traitants.p_step3_titre' => "Choose the location",
    'aide_sous_traitants.p_step3_desc' => "Plant → Area → Zone → Machine cascade, each dropdown unlocking once the previous one is filled (fed by the <a href=\"aide_parc_machine.php\">Machine Fleet</a>).",
    'aide_sous_traitants.p_step4_titre' => "Assign the technician responsible for follow-up",
    'aide_sous_traitants.p_step4_desc' => "A maintenance team member who stays the internal point of contact for this job.",
    'aide_sous_traitants.p_step5_titre' => "Describe the nature of the work",
    'aide_sous_traitants.p_step5_desc' => "Required field, e.g. \"Replacing the belt motor...\". Tick \"BREAKAGE\" if the job follows an accidental breakage.",
    'aide_sous_traitants.p_step6_titre' => "Confirm with \"CREATE THE WORK ORDER\"",
    'aide_sous_traitants.p_step6_desc' => "With no company ticked, no date or no description, the app refuses and shows: \"Please tick at least one company, and fill in the date and description!\"",
    'aide_sous_traitants.callout_tip_numero_bi' => "The <b>BI number</b> (e.g. <code>BI26-014</code>) is generated automatically, like for any job. The assigned technician also receives, right at creation, a <b>0h time entry</b> that officially links them to this BI — it will show up in their schedule from that moment on, even before they've actually logged any time.",
    'aide_sous_traitants.planifier_p2' => "The pencil on a table row opens the same window in <b>\"Edit Schedule\"</b> mode, pre-filled.",
    'aide_sous_traitants.presence_lede' => "A subcontracted job follows a presence cycle, separate from the BI's own status.",
    'aide_sous_traitants.cy_planifie_label' => "Scheduled",
    'aide_sous_traitants.cy_planifie_trig' => "Created via \"NEW JOB\"",
    'aide_sous_traitants.cy_who_vous' => "You",
    'aide_sous_traitants.cy_sursite_label' => "On site",
    'aide_sous_traitants.cy_sursite_trig' => "\"CHECK IN\" button in the table",
    'aide_sous_traitants.cy_pause_label' => "Paused",
    'aide_sous_traitants.cy_pause_trig' => "\"CHECK OUT (PAUSE)\" button on the card",
    'aide_sous_traitants.cy_termine_label' => "Done",
    'aide_sous_traitants.cy_termine_trig' => "\"CLOSE\" button + report",
    'aide_sous_traitants.presence_p2' => "A company \"on site\" shows as a pulsing green card in the \"Currently on site\" panel. The <b>\"CHECK OUT (PAUSE)\"</b> button doesn't close anything: the technician simply leaves the plant, the job moves back into the scheduling table with an orange <b>\"PAUSED\"</b> badge, ready to be \"checked back in\" later.",
    'aide_sous_traitants.cloturer_lede' => "From an \"on site\" card, the green <b>\"CLOSE\"</b> button opens the closing window.",
    'aide_sous_traitants.callout_warn_compte_rendu' => "The <b>\"Job report\"</b> field is required. If you try to close without writing anything: <i>\"Oops! A report is required to close the outside company's job.\"</i>",
    'aide_sous_traitants.cloturer_p2' => "Once confirmed, the job moves to <b>Done</b> status and shifts into the history.",
    'aide_sous_traitants.pdp_lede' => "The PdP is the safety document governing an outside company's job. Its status is calculated automatically from the expiry date entered in the directory.",
    'aide_sous_traitants.tbl1_th_badge' => "Badge",
    'aide_sous_traitants.tbl1_th_condition' => "Condition",
    'aide_sous_traitants.badge_valide' => "PdP Valid",
    'aide_sous_traitants.cond_valide' => "The expiry date is today or in the future.",
    'aide_sous_traitants.badge_expire' => "PdP Expired",
    'aide_sous_traitants.cond_expire' => "The expiry date has passed.",
    'aide_sous_traitants.badge_attente' => "Pending",
    'aide_sous_traitants.cond_attente' => "No expiry date entered for the company.",
    'aide_sous_traitants.pdp_p2' => "Every company has a <b>PdP type</b> in the directory, which changes the display logic:",
    'aide_sous_traitants.route_tag_annuel' => "Annual type",
    'aide_sous_traitants.route_annuel_titre' => "Annual PdP",
    'aide_sous_traitants.route_annuel_desc' => "The status genuinely follows the expiry date (green/red/orange badge).",
    'aide_sous_traitants.route_tag_ponctuel' => "One-off type",
    'aide_sous_traitants.route_ponctuel_titre' => "One-off PdP",
    'aide_sous_traitants.route_ponctuel_desc' => "Redone for every job: the status is always forced to \"ok\" (no false red alert), shown with a specific orange badge and the note \"Linked to the current job\" instead of a date.",
    'aide_sous_traitants.callout_tip_bouclier' => "From the directory, the <b>purple shield</b> icon generates a <b>blank PdP</b> pre-filled with the company's details, ready to be signed (new tab). Once signed and scanned, the PDF attaches to the company record (red PDF icon) and becomes viewable in one click from the scheduling table.",
    'aide_sous_traitants.pdp_p3' => "The <b>\"Missing / Expired PdP\"</b> counter at the top of the page watches <i>every</i> company in the directory, not just the ones with an ongoing job — it's an overall compliance indicator worth checking regularly.",
    'aide_sous_traitants.annuaire_lede' => "Accessible via the <b>\"Manage the company directory\"</b> button, <b>admin-only</b>.",
    'aide_sous_traitants.annuaire_p2' => "Each company record groups: name, contact, phone, email, PdP type, expiry date, and the signed PdP's PDF file.",
    'aide_sous_traitants.tbl2_th_champ' => "Field",
    'aide_sous_traitants.tbl2_th_detail' => "Detail",
    'aide_sous_traitants.row_nom_champ' => "Company name",
    'aide_sous_traitants.row_nom_detail' => "Required.",
    'aide_sous_traitants.row_contact_champ' => "Contact / Phone / Email",
    'aide_sous_traitants.row_contact_detail' => "Optional.",
    'aide_sous_traitants.row_type_champ' => "PdP type",
    'aide_sous_traitants.row_type_detail' => "Annual or One-off — determines how the status is shown (see above).",
    'aide_sous_traitants.row_fin_champ' => "PdP expiry date",
    'aide_sous_traitants.row_fin_detail' => "Date, used to calculate the status badge in Annual mode.",
    'aide_sous_traitants.row_fichier_champ' => "PdP file (PDF)",
    'aide_sous_traitants.row_fichier_detail' => "Upload of a single file, <b>PDF format only</b> — any other format is rejected for security reasons.",
    'aide_sous_traitants.callout_warn_suppression_entreprise' => "Removing a company from the directory is <b>permanent</b>, with a simple confirmation. Jobs already carried out with this company stay visible in the history, but the associated company record no longer exists.",
    'aide_sous_traitants.historique_lede' => "<b>\"HISTORY\"</b> button at the top of the scheduling table: the last 100 closed subcontracted jobs, with BI number (clickable), date, company, machine, technicians who logged time, and the report.",
    'aide_sous_traitants.historique_p2' => "From a company's detail record in the directory, the same history table is filtered <b>to that company only</b> — handy for quickly finding everything a contractor has done on site.",
    'aide_sous_traitants.tbl3_th_action' => "Action",
    'aide_sous_traitants.tbl3_th_technicien' => "Technician",
    'aide_sous_traitants.tbl3_th_admin' => "Admin",
    'aide_sous_traitants.droit1_action' => "View the scheduling / presence / history table",
    'aide_sous_traitants.droit2_action' => "Schedule / edit a job",
    'aide_sous_traitants.droit3_action' => "Check in / out / close",
    'aide_sous_traitants.droit4_action' => "Open the company directory",
    'aide_sous_traitants.droit4_tech' => "Button hidden",
    'aide_sous_traitants.droit5_action' => "Generate a blank PdP",
    'aide_sous_traitants.droit5_tech' => "Link hidden",
    'aide_sous_traitants.astuces_li1' => "<b>The \"This week / This month / All\" filter</b> at the top of the scheduling table isn't active for now — it has no effect on the display.",
    'aide_sous_traitants.astuces_li2' => "<b>Check the \"Missing / Expired PdP\" counter regularly</b> — it's the only place that alerts you to companies out of safety compliance, even with no job in progress.",
    'aide_sous_traitants.astuces_li3' => "<b>Don't confuse \"CHECK OUT (PAUSE)\" and \"CLOSE\"</b>: the first keeps the job open for a later resumption, the second ends it permanently and requires a report.",
    'aide_sous_traitants.astuces_li4' => "<b>A \"One-off\" PdP</b> doesn't need a constantly up-to-date expiry date — it's normal for it to always show as valid.",
    'aide_sous_traitants.gloss1_dt' => "PdP",
    'aide_sous_traitants.gloss1_dd' => "Prevention Plan — mandatory safety document governing an outside company's job.",
    'aide_sous_traitants.gloss2_dt' => "On site",
    'aide_sous_traitants.gloss2_dd' => "Status of a company physically present on site right now.",
    'aide_sous_traitants.gloss3_dt' => "Paused",
    'aide_sous_traitants.gloss3_dd' => "An unfinished job whose technician has temporarily left the site.",
    'aide_sous_traitants.gloss4_dt' => "Directory",
    'aide_sous_traitants.gloss4_dd' => "The list of registered outside companies, with their details and their PdP.",
    'aide_sous_traitants.devnote_intro' => "Points noticed while reading the code, worth keeping in mind on the admin side:",
    'aide_sous_traitants.devnote_li1' => "The \"This week / This month / All\" selector on the scheduling table has no associated JS logic — cosmetic for now.",
    'aide_sous_traitants.devnote_li2' => "The directory's protection (button hidden from non-admins) is <b>visual only, PHP-side</b>: the <code>action_entreprise</code> server handler doesn't recheck the role.",
    'aide_sous_traitants.devnote_li3' => "Only the <code>.pdf</code> extension is accepted for PdP uploads, checked server-side — a good practice worth keeping.",
    'aide_sous_traitants.devnote_li4' => "Removing a company from the directory doesn't check related jobs (<code>entreprise_ext_id</code> becomes orphaned but the name still shows via the join frozen at query time).",

